window.CustomStepBuiltinScripts={"111卖点图后处理.js":"/**\r\n * 111 卖点图后处理脚本 — SDK v2.2 + @contract\r\n *\r\n * @contract\r\n * @needs canvas:main\r\n * @needs row:product\r\n * @needs api:deepseek\r\n * @roles polo material|craft|design|feature\r\n * @roles shirt material|craft|print|feature\r\n * @roles t-shirt material|weight|feature|style\r\n * @roles hooded-sweatshirt material|craft|weight|feature\r\n * @roles non-hooded-sweatshirt material|craft|weight|feature\r\n * @supports single,batch\r\n * @fallback throw\r\n * @timeout 120000\r\n *\r\n * @resource productRow row \"当前产品行（Excel）\" from:currentSet.row\r\n *\r\n * 数据来源：ctx.data.excelRow —— 当前导入 Excel 的当前产品行快照（含文件/工作表/实际行号）。\r\n * 按真实 Excel 列名取值；「类目」列决定卖点来源：\r\n *   polo → 材质/工艺/设计/产品特性；shirt → 材质/工艺/印花方法/产品特性；\r\n *   帽衫与无帽卫衣 → 材质/工艺/面料克重/产品特性；t-shirt → 材质/面料克重/产品特性/样式。\r\n * ONNX session 通过 window 全局缓存跨注入复用（getOrCreateU2NetSession）。\r\n */\r\nCustomJsSDK.run(async ctx => {\r\n    const { canvas, ctx: g, img } = ctx;\r\n\r\n    // 当前产品行快照（真实 Excel 列名；文件/工作表/实际行号一并锁定，执行中换行不影响本任务）\r\n    const task = ctx.data.excelRow;\r\n    if (!task) throw new Error('缺少当前产品行数据（excelRow）');\r\n    ctx.log('[111JS] ' + task.describe() + '，列数: ' + task.headers.length);\r\n\r\n    // 从当前产品行构建标注数据\r\n    function buildSellingPointAnnotations() {\r\n        const rawTitle = ctx.data.cell('标题');\r\n        if (!rawTitle) throw new Error('「标题」列内容为空，无法标注卖点图');\r\n        const words = rawTitle.split(/\\s+/).filter(w => w);\r\n        const titleLines = [];\r\n        for (let i = 0; i < Math.min(words.length, 12); i += 4) {\r\n            titleLines.push(words.slice(i, i + 4).join(' '));\r\n        }\r\n        const groupVal = ctx.data.category();\r\n        let sellpointRoles;\r\n        if (groupVal === 'polo') {\r\n            sellpointRoles = ['material', 'craft', 'design', 'feature'];\r\n            ctx.log('[111JS] 类目: Polo shirt → 卖点来源: 材质/工艺/设计/产品特性');\r\n        } else if (groupVal === 'shirt') {\r\n            sellpointRoles = ['material', 'craft', 'print', 'feature'];\r\n            ctx.log('[111JS] 类目: Shirt → 卖点来源: 材质/工艺/印花方法/产品特性');\r\n        } else if (groupVal === 'hooded-sweatshirt' || groupVal === 'non-hooded-sweatshirt') {\r\n            sellpointRoles = ['material', 'craft', 'weight', 'feature'];\r\n            ctx.log('[111JS] 类目: Hoodies & Sweatshirts → 卖点来源: 材质/工艺/面料克重/产品特性');\r\n        } else if (groupVal === 't-shirt') {\r\n            sellpointRoles = ['material', 'weight', 'feature', 'style'];\r\n            ctx.log('[111JS] 类目: T-shirt → 卖点来源: 材质/面料克重/产品特性/样式');\r\n        } else {\r\n            throw new Error('类目未配置卖点来源：' + (groupVal || '空'));\r\n        }\r\n\r\n        const sellingPoints = [];\r\n        const seen = new Set();\r\n\r\n        for (const roleName of sellpointRoles) {\r\n            let val = ctx.data.role(roleName).value;\r\n            if (!val || ['none', 'n/a', 'na'].includes(val.toLowerCase())) continue;\r\n\r\n            if (roleName === 'weight') {\r\n                const match = val.match(/\\d+\\.?\\d*/);\r\n                if (match) {\r\n                    const w = Math.round(parseFloat(match[0]));\r\n                    if (w <= 180) {\r\n                        val = 'Lightweight fabric ' + w + 'g';\r\n                    } else if (w >= 240) {\r\n                        val = 'Premium heavyweight ' + w + 'g';\r\n                    } else {\r\n                        val = 'Just the right weight ' + w + 'g';\r\n                    }\r\n                }\r\n            }\r\n\r\n            if (roleName === 'feature') {\r\n                if (groupVal === 't-shirt') {\r\n                    // t-shirt：逗号优先、不足则按换行，只取第一项\r\n                    let parts = val.split(',').map(p => p.trim()).filter(p => p);\r\n                    if (parts.length <= 1) {\r\n                        parts = val.split('\\n').map(p => p.trim()).filter(p => p);\r\n                    }\r\n                    if (parts.length > 0) {\r\n                        const firstItem = parts[0];\r\n                        if (!seen.has(firstItem)) {\r\n                            seen.add(firstItem);\r\n                            sellingPoints.push(firstItem);\r\n                        }\r\n                    }\r\n                } else {\r\n                    // 其余类目：逗号优先，最多 3 项\r\n                    for (const sep of [',', '\\n']) {\r\n                        const parts = val.split(sep).map(p => p.trim()).filter(p => p);\r\n                        if (parts.length > 0) {\r\n                            for (const p of parts.slice(0, 3)) {\r\n                                if (!seen.has(p)) {\r\n                                    seen.add(p);\r\n                                    sellingPoints.push(p);\r\n                                }\r\n                            }\r\n                            break;\r\n                        }\r\n                    }\r\n                }\r\n            } else {\r\n                if (!seen.has(val)) {\r\n                    seen.add(val);\r\n                    sellingPoints.push(val);\r\n                }\r\n            }\r\n        }\r\n\r\n        if (sellingPoints.length === 0) throw new Error('卖点属性均缺失，无法标注卖点图');\r\n\r\n        return { titleLines, sellingPoints: sellingPoints.slice(0, 4) };\r\n    }\r\n\r\n    let { titleLines, sellingPoints } = buildSellingPointAnnotations();\r\n    let w = canvas.width;\r\n    let h = canvas.height;\r\n\r\n    const COLS = 500;\r\n    const ROWS = 500;\r\n    const SCALE_FACTOR = COLS / 60;\r\n\r\n    let brandBlacklistData = { brands: [] };\r\n\r\n    // 中英文标题直接来自任务冻结行，按完整单词截短用于排版，不再依赖另一个模型或 API Key。\r\n    async function compactProductTitle(title, maxChars) {\r\n        const parts=String(title).split(/\\s+\\/\\s+/);\r\n        const banned=brandBlacklistData.brands||[];\r\n        const clean=text=>banned.reduce((v,brand)=>v.replace(new RegExp(brand.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&'),'gi'),''),text).replace(/\\s+/g,' ').trim();\r\n        const en=clean(parts[0]||'');\r\n        const words=en.split(/\\s+/);let compact='';\r\n        for(const word of words){if((compact+' '+word).trim().length>maxChars)break;compact=(compact+' '+word).trim();}\r\n        if(!compact)throw new Error('Product title is empty');\r\n        return {en:compact,cn:clean(parts.slice(1).join(' / ')).slice(0,maxChars)};\r\n    }\r\n\r\n    // 优先用 AI 精简标题（由扩展后台代发请求，避开页面 file:// 的跨域限制）；\r\n    // 任何失败都回退到按单词截断，保证不阻塞出图。\r\n    async function aiCompactTitle(title, maxChars) {\r\n        try {\r\n            const extId = (typeof EXTENSION_ID === 'string' && EXTENSION_ID) ? EXTENSION_ID : (localStorage.getItem('polo_extension_id') || '');\r\n            if (!extId || typeof chrome === 'undefined' || !chrome.runtime || !chrome.runtime.sendMessage) return null;\r\n            const resp = await new Promise(resolve => {\r\n                try {\r\n                    chrome.runtime.sendMessage(extId, { action: 'aiSimplifyTitle', title, maxChars, apiConfig: options.apiConfig }, r => {\r\n                        if (chrome.runtime.lastError) resolve(null); else resolve(r);\r\n                    });\r\n                } catch (_) { resolve(null); }\r\n            });\r\n            if (resp && resp.ok && resp.title) return { en: resp.title, cn: '' };\r\n            if (resp && resp.error) console.warn('[111] AI 精简失败，回退截断：' + resp.error);\r\n        } catch (_) {}\r\n        return null;\r\n    }\r\n\r\n    function rgbToHsv(r, g, b) {\r\n        r /= 255; g /= 255; b /= 255;\r\n        let max = Math.max(r, g, b), min = Math.min(r, g, b);\r\n        let h, s, v = max;\r\n        let d = max - min;\r\n        s = max === 0 ? 0 : d / max;\r\n        if (max === min) {\r\n            h = 0;\r\n        } else {\r\n            switch (max) {\r\n                case r: h = ((g - b) / d + (g < b ? 6 : 0)) / 6; break;\r\n                case g: h = ((b - r) / d + 2) / 6; break;\r\n                case b: h = ((r - g) / d + 4) / 6; break;\r\n            }\r\n        }\r\n        return [h, s, v];\r\n    }\r\n\r\n    function hsvToRgb(h, s, v) {\r\n        let r, g, b;\r\n        let i = Math.floor(h * 6);\r\n        let f = h * 6 - i;\r\n        let p = v * (1 - s);\r\n        let q = v * (1 - f * s);\r\n        let t = v * (1 - (1 - f) * s);\r\n        switch (i % 6) {\r\n            case 0: r = v; g = t; b = p; break;\r\n            case 1: r = q; g = v; b = p; break;\r\n            case 2: r = p; g = v; b = t; break;\r\n            case 3: r = p; g = q; b = v; break;\r\n            case 4: r = t; g = p; b = v; break;\r\n            case 5: r = v; g = p; b = q; break;\r\n        }\r\n        return [Math.floor(r * 255), Math.floor(g * 255), Math.floor(b * 255)];\r\n    }\r\n\r\n    function getTextWidth(ctx, text) {\r\n        let m = ctx.measureText(text);\r\n        return m.width;\r\n    }\r\n\r\n    // 抠图（U2Net ONNX）已抽到共享实现：ctx.rembg.rembgRemoveBackground\r\n    // —— 111卖点图 / 111扩图 / 444扩图 三份实现实测逻辑一致，集中到 SDK 后可避免三处漂移\r\n    //    （session 全局缓存键、320×320 归一化、LANCZOS 回缩放等细节只维护一处）\r\n    const { rembgRemoveBackground, getOrCreateU2NetSession } = ctx.rembg;\r\n\r\n    // 参数 g 为画布 2D 上下文（外层解构 ctx: g 得到）。\r\n    // 注意：参数名必须用 g，不能用 ctx —— 否则会遮蔽外层 SDK ctx，导致 ctx.log(...) 报 TypeError。\r\n    // 函数内 ctx.log/warn 调用访问的是外层 SDK ctx 闭包（非本函数参数）。\r\n    async function annotateImageOnCanvas(canvas, g, img, titleLines, sellingPoints) {\r\n        sellingPoints = sellingPoints.map(sp => ctx.draw.formatDisplayText(sp));\r\n        let n_sp = sellingPoints.length;\r\n\r\n        let cw = w / COLS;\r\n        let ch = h / ROWS;\r\n\r\n        let maskCanvas = await rembgRemoveBackground(img);\r\n        if (maskCanvas.width !== w || maskCanvas.height !== h) {\r\n            let scaledMask = document.createElement('canvas');\r\n            scaledMask.width = w;\r\n            scaledMask.height = h;\r\n            let scaledCtx = scaledMask.getContext('2d');\r\n            scaledCtx.drawImage(maskCanvas, 0, 0, w, h);\r\n            maskCanvas = scaledMask;\r\n        }\r\n        let maskCtx = maskCanvas.getContext('2d');\r\n        let maskData = maskCtx.getImageData(0, 0, maskCanvas.width, maskCanvas.height);\r\n        let maskPx = maskData.data;\r\n\r\n        // ===== 自适应阈值：先收集所有 mask 像素值做分布分析 =====\r\n        let maskVals = [];\r\n        for (let y = 0; y < maskCanvas.height; y++) {\r\n            for (let x = 0; x < maskCanvas.width; x++) {\r\n                maskVals.push(maskPx[(y * maskCanvas.width + x) * 4]);\r\n            }\r\n        }\r\n        maskVals.sort((a, b) => a - b);\r\n        let p50 = maskVals[Math.floor(maskVals.length * 0.5)];\r\n        let p10 = maskVals[Math.floor(maskVals.length * 0.1)];\r\n        let p90 = maskVals[Math.floor(maskVals.length * 0.9)];\r\n\r\n        // 用固定阈值 30 先做一遍，如果 >= 98% 都被判为衣服，说明模型输出太软，改用自适应阈值\r\n        let clothThreshold = 30;\r\n        let raw_cloth_pct;\r\n        {\r\n            let tc = 0, tp = 0;\r\n            for (let gy = 0; gy < ROWS; gy++) {\r\n                for (let gx = 0; gx < COLS; gx++) {\r\n                    let y1 = Math.floor(gy * ch), y2 = Math.floor((gy + 1) * ch);\r\n                    let x1 = Math.floor(gx * cw), x2 = Math.floor((gx + 1) * cw);\r\n                    for (let y = y1; y < Math.min(y2, maskCanvas.height); y++) {\r\n                        for (let x = x1; x < Math.min(x2, maskCanvas.width); x++) {\r\n                            tp++;\r\n                            if (maskPx[(y * maskCanvas.width + x) * 4] > 30) tc++;\r\n                        }\r\n                    }\r\n                }\r\n            }\r\n            raw_cloth_pct = tc / tp;\r\n        }\r\n\r\n        if (raw_cloth_pct > 0.98) {\r\n            // 模型区分度不足，用 P70 作为阈值切分前景/背景\r\n            clothThreshold = maskVals[Math.floor(maskVals.length * 0.7)];\r\n            clothThreshold = Math.max(60, Math.min(clothThreshold, 200));\r\n            ctx.log(`  [debug] 固定阈值30导致衣服占比${(raw_cloth_pct * 100).toFixed(1)}%，切换自适应阈值: ${clothThreshold} (P70), P10=${p10}, P50=${p50}, P90=${p90}`);\r\n        } else {\r\n            ctx.log(`  [debug] mask分布: P10=${p10}, P50=${p50}, P90=${p90}`);\r\n        }\r\n\r\n        // ===== 用最终阈值做网格分类 =====\r\n        let gg = Array(ROWS).fill().map(() => Array(COLS).fill(false));\r\n        let total_cloth_pixels = 0, total_pixels = 0;\r\n\r\n        for (let gy = 0; gy < ROWS; gy++) {\r\n            for (let gx = 0; gx < COLS; gx++) {\r\n                let y1 = Math.floor(gy * ch), y2 = Math.floor((gy + 1) * ch);\r\n                let x1 = Math.floor(gx * cw), x2 = Math.floor((gx + 1) * cw);\r\n                let ct = 0, ac = 0;\r\n                for (let y = y1; y < Math.min(y2, maskCanvas.height); y++) {\r\n                    for (let x = x1; x < Math.min(x2, maskCanvas.width); x++) {\r\n                        ct++;\r\n                        if (maskPx[(y * maskCanvas.width + x) * 4] > clothThreshold) ac++;\r\n                    }\r\n                }\r\n                total_pixels += ct;\r\n                total_cloth_pixels += ac;\r\n                if (ct > 0 && ac / ct > 0.05) gg[gy][gx] = true;\r\n            }\r\n        }\r\n\r\n        ctx.log(`  [debug] rembg mask统计: 总像素=${total_pixels}, 衣服像素=${total_cloth_pixels}, 占比=${((total_cloth_pixels/total_pixels)*100).toFixed(2)}%`);\r\n\r\n        let visited = Array(ROWS).fill().map(() => Array(COLS).fill(false));\r\n        let components = [];\r\n\r\n        for (let gy = 0; gy < ROWS; gy++) {\r\n            for (let gx = 0; gx < COLS; gx++) {\r\n                if (gg[gy][gx] && !visited[gy][gx]) {\r\n                    let comp = [];\r\n                    let q = [[gy, gx]];\r\n                    visited[gy][gx] = true;\r\n                    while (q.length > 0) {\r\n                        let [cy, cx] = q.shift();\r\n                        comp.push([cy, cx]);\r\n                        let dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]];\r\n                        for (let [dy, dx] of dirs) {\r\n                            let ny = cy + dy, nx = cx + dx;\r\n                            if (ny >= 0 && ny < ROWS && nx >= 0 && nx < COLS && gg[ny][nx] && !visited[ny][nx]) {\r\n                                visited[ny][nx] = true;\r\n                                q.push([ny, nx]);\r\n                            }\r\n                        }\r\n                    }\r\n                    components.push(comp);\r\n                }\r\n            }\r\n        }\r\n\r\n        if (components.length > 0) {\r\n            let largest = components.reduce((a, b) => a.length > b.length ? a : b);\r\n            gg = Array(ROWS).fill().map(() => Array(COLS).fill(false));\r\n            for (let [gy, gx] of largest) {\r\n                gg[gy][gx] = true;\r\n            }\r\n        }\r\n\r\n        let g_pixels = [];\r\n        let bg_pixels = [];\r\n        let imgData = g.getImageData(0, 0, w, h);\r\n        let pxData = imgData.data;\r\n\r\n        for (let gy = 0; gy < ROWS; gy++) {\r\n            for (let gx = 0; gx < COLS; gx++) {\r\n                let y1 = Math.floor(gy * ch);\r\n                let y2 = Math.floor((gy + 1) * ch);\r\n                let x1 = Math.floor(gx * cw);\r\n                let x2 = Math.floor((gx + 1) * cw);\r\n                let rs = 0, gs = 0, bs = 0, ct = 0;\r\n                for (let y = y1; y < Math.min(y2, h); y++) {\r\n                    for (let x = x1; x < Math.min(x2, w); x++) {\r\n                        let idx = (y * w + x) * 4;\r\n                        rs += pxData[idx];\r\n                        gs += pxData[idx + 1];\r\n                        bs += pxData[idx + 2];\r\n                        ct++;\r\n                    }\r\n                }\r\n                if (ct > 0) {\r\n                    let avg_r = Math.floor(rs / ct);\r\n                    let avg_g = Math.floor(gs / ct);\r\n                    let avg_b = Math.floor(bs / ct);\r\n                    if (gg[gy][gx]) {\r\n                        g_pixels.push([avg_r, avg_g, avg_b]);\r\n                    } else {\r\n                        bg_pixels.push([avg_r, avg_g, avg_b]);\r\n                    }\r\n                }\r\n            }\r\n        }\r\n\r\n        let avg_garm = [128, 128, 128];\r\n        if (g_pixels.length > 0) {\r\n            avg_garm = [\r\n                Math.floor(g_pixels.reduce((sum, p) => sum + p[0], 0) / g_pixels.length),\r\n                Math.floor(g_pixels.reduce((sum, p) => sum + p[1], 0) / g_pixels.length),\r\n                Math.floor(g_pixels.reduce((sum, p) => sum + p[2], 0) / g_pixels.length)\r\n            ];\r\n        }\r\n\r\n        let avg_bg = [128, 128, 128];\r\n        if (bg_pixels.length > 0) {\r\n            avg_bg = [\r\n                Math.floor(bg_pixels.reduce((sum, p) => sum + p[0], 0) / bg_pixels.length),\r\n                Math.floor(bg_pixels.reduce((sum, p) => sum + p[1], 0) / bg_pixels.length),\r\n                Math.floor(bg_pixels.reduce((sum, p) => sum + p[2], 0) / bg_pixels.length)\r\n            ];\r\n        }\r\n\r\n        let bg_lum = avg_bg[0] * 299 + avg_bg[1] * 587 + avg_bg[2] * 114;\r\n        let is_dark = bg_lum < 130000;\r\n        let tc = is_dark ? [255, 255, 255] : [40, 40, 50];\r\n\r\n        ctx.log(`  [debug] 衣服颜色: RGB(${avg_garm.join(',')}), 背景颜色: RGB(${avg_bg.join(',')}), 背景亮度=${bg_lum}, is_dark=${is_dark}, 标题颜色=${tc}`);\r\n\r\n        let gys = [];\r\n        for (let gy = 0; gy < ROWS; gy++) {\r\n            if (gg[gy].some(x => x)) gys.push(gy);\r\n        }\r\n        let g_top = gys.length > 0 ? gys[0] : Math.floor(ROWS / 2);\r\n        let g_bot = gys.length > 0 ? gys[gys.length - 1] : Math.floor(ROWS * 3 / 4);\r\n\r\n        let gxs = [];\r\n        for (let gx = 0; gx < COLS; gx++) {\r\n            for (let gy = 0; gy < ROWS; gy++) {\r\n                if (gg[gy][gx]) { gxs.push(gx); break; }\r\n            }\r\n        }\r\n        let g_left = gxs.length > 0 ? gxs[0] : Math.floor(COLS / 4);\r\n        let g_right = gxs.length > 0 ? gxs[gxs.length - 1] : Math.floor(COLS * 3 / 4);\r\n\r\n        let zone = Array(ROWS).fill().map(() => Array(COLS).fill(0));\r\n        for (let gy = 0; gy < g_top; gy++) {\r\n            for (let gx = 0; gx < COLS; gx++) zone[gy][gx] = 2;\r\n        }\r\n        for (let gy = 0; gy < ROWS; gy++) {\r\n            for (let gx = 0; gx < COLS; gx++) {\r\n                if (gg[gy][gx]) zone[gy][gx] = 1;\r\n            }\r\n        }\r\n\r\n        let tr2 = g_top;\r\n        let cloth_row_range = [g_top, g_bot];\r\n\r\n        let cloth_cells = [];\r\n        for (let gy = 0; gy < ROWS; gy++) {\r\n            for (let gx = 0; gx < COLS; gx++) {\r\n                if (gg[gy][gx]) cloth_cells.push([gy, gx]);\r\n            }\r\n        }\r\n\r\n        let cloth_center_gx = Math.floor(COLS / 2);\r\n        if (cloth_cells.length > 0) {\r\n            let cloth_gxs = cloth_cells.map(c => c[1]);\r\n            cloth_center_gx = Math.floor(cloth_gxs.reduce((sum, gx) => sum + gx, 0) / cloth_gxs.length);\r\n        }\r\n\r\n        let cloth_position = 'center';\r\n        let left_blank_cols = g_left;\r\n        let right_blank_cols = COLS - 1 - g_right;\r\n        let total_cols = left_blank_cols + right_blank_cols;\r\n        let diff_ratio = total_cols > 0 ? Math.abs(left_blank_cols - right_blank_cols) / total_cols : 0;\r\n\r\n        ctx.log(`  位置检测: 左边空白列=${left_blank_cols}, 右边空白列=${right_blank_cols}, 比例差=${(diff_ratio * 100).toFixed(2)}%`);\r\n        if (left_blank_cols < right_blank_cols && diff_ratio > 0.15) {\r\n            cloth_position = 'left';\r\n            ctx.log('  → 衣服靠左');\r\n        } else if (right_blank_cols < left_blank_cols && diff_ratio > 0.15) {\r\n            cloth_position = 'right';\r\n            ctx.log('  → 衣服靠右');\r\n        } else {\r\n            cloth_position = 'center';\r\n            ctx.log('  → 衣服居中');\r\n        }\r\n\r\n        // 垂直方向区域信息提取：统计某列/某行的连通格子，用于卖点胶囊的纵向定位\r\n        function get_region_info_v(data, name, default_gy) {\r\n            if (!data || data.length === 0) {\r\n                return { name: name, gy_center: default_gy, gxs: [], count: 0,\r\n                         gx_min: 0, gx_max: 0, gy_min: 0, gy_max: 0,\r\n                         full_data: data, orient: 'v' };\r\n            }\r\n            let all_gxs = [];\r\n            let all_gys = [];\r\n            let total_cells = 0;\r\n            for (let [gy, gxs_row] of data) {\r\n                all_gxs = all_gxs.concat(gxs_row);\r\n                all_gys.push(gy);\r\n                total_cells += gxs_row.length;\r\n            }\r\n            return {\r\n                name: name,\r\n                gy_center: data[Math.floor(data.length / 2)][0],\r\n                gxs: [...new Set(all_gxs)],\r\n                count: total_cells,\r\n                gx_min: Math.min(...all_gxs),\r\n                gx_max: Math.max(...all_gxs),\r\n                gy_min: Math.min(...all_gys),\r\n                gy_max: Math.max(...all_gys),\r\n                full_data: data,\r\n                orient: 'v'\r\n            };\r\n        }\r\n\r\n        // 水平方向区域信息提取：与 get_region_info_v 对称，用于横向定位\r\n        function get_region_info_h(data, name, default_gy) {\r\n            if (!data || data.length === 0) {\r\n                return { name: name, gy_center: default_gy, gxs: [], count: 0,\r\n                         gx_min: 0, gx_max: 0, gy_min: 0, gy_max: 0,\r\n                         full_data: data, orient: 'h' };\r\n            }\r\n            let cols = data.map(d => d[0]);\r\n            let all_row_gys = [];\r\n            let total_cells = 0;\r\n            for (let [gx, row_gys] of data) {\r\n                all_row_gys = all_row_gys.concat(row_gys);\r\n                total_cells += row_gys.length;\r\n            }\r\n            all_row_gys.sort((a, b) => a - b);\r\n            return {\r\n                name: name,\r\n                gy_center: all_row_gys[Math.floor(all_row_gys.length / 2)],\r\n                gxs: cols,\r\n                count: total_cells,\r\n                gx_min: Math.min(...cols),\r\n                gx_max: Math.max(...cols),\r\n                gy_min: Math.min(...all_row_gys),\r\n                gy_max: Math.max(...all_row_gys),\r\n                full_data: data,\r\n                orient: 'h'\r\n            };\r\n        }\r\n\r\n        let selected_regions = [];\r\n\r\n        if (cloth_position === 'left') {\r\n            ctx.log('  靠右生成区域（衣服靠左，标注放右侧）：');\r\n            let total_rows = g_bot - g_top + 1;\r\n            let zone_top = Math.max(0, g_top - Math.floor(total_rows * 0.05));\r\n            let zone_bot = Math.min(ROWS - 1, g_bot + Math.floor(total_rows * 0.10));\r\n            let zone_height = zone_bot - zone_top + 1;\r\n\r\n            let scan_start_gx = g_right;\r\n            let scan_end_gx = COLS - 1;\r\n            let band_height = Math.floor(zone_height / n_sp);\r\n\r\n            let regions = [];\r\n            for (let i = 0; i < n_sp; i++) {\r\n                let band_start = zone_top + i * band_height;\r\n                let band_end = zone_top + (i + 1) * band_height - 1;\r\n                if (i === n_sp - 1) band_end = zone_bot;\r\n                let band_center_gy = Math.floor((band_start + band_end) / 2);\r\n                let region_data = [];\r\n                for (let gy = band_start; gy <= band_end; gy++) {\r\n                    let blank_gxs = [];\r\n                    for (let gx = scan_start_gx; gx <= scan_end_gx; gx++) {\r\n                        if (zone[gy][gx] === 0) blank_gxs.push(gx);\r\n                    }\r\n                    if (blank_gxs.length > 0) region_data.push([gy, blank_gxs]);\r\n                }\r\n                regions.push(get_region_info_v(region_data, `右侧${i + 1}`, band_center_gy));\r\n            }\r\n\r\n            regions = regions.filter(r => r.count > 0);\r\n            for (let reg of regions) {\r\n                ctx.log(`    ${reg.name}: ${reg.count}个格子`);\r\n            }\r\n\r\n            let sp_sorted = sellingPoints.map((_, i) => i).sort((a, b) => sellingPoints[b].length - sellingPoints[a].length);\r\n            let regions_sorted = regions.map((r, i) => ({ r, i })).sort((a, b) => b.r.count - a.r.count);\r\n            selected_regions = Array(n_sp).fill(null);\r\n            let used_regions = new Set();\r\n\r\n            for (let idx of sp_sorted) {\r\n                for (let { r, i } of regions_sorted) {\r\n                    if (!used_regions.has(i)) {\r\n                        selected_regions[idx] = r;\r\n                        used_regions.add(i);\r\n                        break;\r\n                    }\r\n                }\r\n            }\r\n\r\n            for (let i = 0; i < n_sp; i++) {\r\n                if (!selected_regions[i]) {\r\n                    selected_regions[i] = {\r\n                        name: `右侧${i + 1}`,\r\n                        gy_center: zone_top + (i + 0.5) * band_height,\r\n                        gxs: [g_right + 5],\r\n                        count: 1,\r\n                        gx_min: g_right,\r\n                        gx_max: COLS - 1,\r\n                        full_data: [],\r\n                        orient: 'v'\r\n                    };\r\n                }\r\n            }\r\n\r\n        } else if (cloth_position === 'right') {\r\n            ctx.log('  靠左生成区域（衣服靠右，标注放左侧）：');\r\n            let total_rows = g_bot - g_top + 1;\r\n            let zone_top = Math.max(0, g_top - Math.floor(total_rows * 0.05));\r\n            let zone_bot = Math.min(ROWS - 1, g_bot + Math.floor(total_rows * 0.10));\r\n            let zone_height = zone_bot - zone_top + 1;\r\n\r\n            let scan_start_gx = 0;\r\n            let scan_end_gx = g_left;\r\n            let band_height = Math.floor(zone_height / n_sp);\r\n\r\n            let regions = [];\r\n            for (let i = 0; i < n_sp; i++) {\r\n                let band_start = zone_top + i * band_height;\r\n                let band_end = zone_top + (i + 1) * band_height - 1;\r\n                if (i === n_sp - 1) band_end = zone_bot;\r\n                let band_center_gy = Math.floor((band_start + band_end) / 2);\r\n                let region_data = [];\r\n                for (let gy = band_start; gy <= band_end; gy++) {\r\n                    let blank_gxs = [];\r\n                    for (let gx = scan_start_gx; gx <= scan_end_gx; gx++) {\r\n                        if (zone[gy][gx] === 0) blank_gxs.push(gx);\r\n                    }\r\n                    if (blank_gxs.length > 0) region_data.push([gy, blank_gxs]);\r\n                }\r\n                regions.push(get_region_info_v(region_data, `左侧${i + 1}`, band_center_gy));\r\n            }\r\n\r\n            regions = regions.filter(r => r.count > 0);\r\n            for (let reg of regions) {\r\n                ctx.log(`    ${reg.name}: ${reg.count}个格子`);\r\n            }\r\n\r\n            let sp_sorted = sellingPoints.map((_, i) => i).sort((a, b) => sellingPoints[b].length - sellingPoints[a].length);\r\n            let regions_sorted = regions.map((r, i) => ({ r, i })).sort((a, b) => b.r.count - a.r.count);\r\n            selected_regions = Array(n_sp).fill(null);\r\n            let used_regions = new Set();\r\n\r\n            for (let idx of sp_sorted) {\r\n                for (let { r, i } of regions_sorted) {\r\n                    if (!used_regions.has(i)) {\r\n                        selected_regions[idx] = r;\r\n                        used_regions.add(i);\r\n                        break;\r\n                    }\r\n                }\r\n            }\r\n\r\n            for (let i = 0; i < n_sp; i++) {\r\n                if (!selected_regions[i]) {\r\n                    selected_regions[i] = {\r\n                        name: `左侧${i + 1}`,\r\n                        gy_center: zone_top + (i + 0.5) * band_height,\r\n                        gxs: [g_left - 5],\r\n                        count: 1,\r\n                        gx_min: 0,\r\n                        gx_max: g_left,\r\n                        full_data: [],\r\n                        orient: 'v'\r\n                    };\r\n                }\r\n            }\r\n\r\n        } else {\r\n            let total_rows = g_bot - g_top + 1;\r\n            let half = Math.floor(total_rows / 2);\r\n            let band1_gy_center = Math.floor((g_top + (g_top + half - 1)) / 2);\r\n            let band2_gy_center = Math.floor(((g_top + half) + g_bot) / 2);\r\n\r\n            let band_height_old = Math.floor(3 * SCALE_FACTOR);\r\n            let edge_margin_old = Math.floor(1 * SCALE_FACTOR);\r\n\r\n            let region0_data = [];\r\n            let region1_data = [];\r\n            let region2_data = [];\r\n            let region3_data = [];\r\n\r\n            let startGy = Math.max(edge_margin_old, band1_gy_center - band_height_old);\r\n            let endGy = Math.min(ROWS - edge_margin_old, band1_gy_center + band_height_old);\r\n            for (let gy = startGy; gy <= endGy; gy++) {\r\n                if (gy < tr2) continue;\r\n                let left_blank = [];\r\n                for (let gx = edge_margin_old; gx < cloth_center_gx; gx++) {\r\n                    if (zone[gy][gx] === 0) left_blank.push(gx);\r\n                }\r\n                let right_blank = [];\r\n                for (let gx = cloth_center_gx; gx < COLS - edge_margin_old; gx++) {\r\n                    if (zone[gy][gx] === 0) right_blank.push(gx);\r\n                }\r\n                if (left_blank.length > 0) region0_data.push([gy, left_blank]);\r\n                if (right_blank.length > 0) region1_data.push([gy, right_blank]);\r\n            }\r\n\r\n            startGy = Math.max(edge_margin_old, band2_gy_center - band_height_old);\r\n            endGy = Math.min(ROWS - edge_margin_old, band2_gy_center + band_height_old);\r\n            for (let gy = startGy; gy <= endGy; gy++) {\r\n                let left_blank = [];\r\n                for (let gx = edge_margin_old; gx < cloth_center_gx; gx++) {\r\n                    if (zone[gy][gx] === 0) left_blank.push(gx);\r\n                }\r\n                let right_blank = [];\r\n                for (let gx = cloth_center_gx; gx < COLS - edge_margin_old; gx++) {\r\n                    if (zone[gy][gx] === 0) right_blank.push(gx);\r\n                }\r\n                if (left_blank.length > 0) region2_data.push([gy, left_blank]);\r\n                if (right_blank.length > 0) region3_data.push([gy, right_blank]);\r\n            }\r\n\r\n            let region0 = get_region_info_v(region0_data, '左上', band1_gy_center);\r\n            let region1 = get_region_info_v(region1_data, '右上', band1_gy_center);\r\n            let region2 = get_region_info_v(region2_data, '左下', band2_gy_center);\r\n            let region3 = get_region_info_v(region3_data, '右下', band2_gy_center);\r\n\r\n            let gx_span = g_right - g_left;\r\n            let gx_left_inner = g_left + Math.floor(gx_span / 5);\r\n            let gx_right_inner = g_right - Math.floor(gx_span / 5);\r\n            let bottom_mid_data = [];\r\n\r\n            let startGx = Math.max(edge_margin_old, gx_left_inner);\r\n            let endGx = Math.min(COLS - edge_margin_old, gx_right_inner);\r\n            for (let gx = startGx; gx <= endGx; gx++) {\r\n                let below_blank = [];\r\n                for (let gy = g_bot + 1; gy < ROWS - edge_margin_old; gy++) {\r\n                    if (zone[gy][gx] === 0) below_blank.push(gy);\r\n                }\r\n                if (below_blank.length > 0) bottom_mid_data.push([gx, below_blank]);\r\n            }\r\n            let region_bottom_mid = get_region_info_h(bottom_mid_data, '下中', g_bot + band_height_old);\r\n\r\n            let middle_gy = Math.floor((band1_gy_center + band2_gy_center) / 2);\r\n            let middle_data = [];\r\n\r\n            startGy = Math.max(edge_margin_old, middle_gy - band_height_old);\r\n            endGy = Math.min(ROWS - edge_margin_old, middle_gy + band_height_old);\r\n            for (let gy = startGy; gy <= endGy; gy++) {\r\n                if (gy < tr2) continue;\r\n                let right_blank = [];\r\n                for (let gx = cloth_center_gx; gx < COLS - edge_margin_old; gx++) {\r\n                    if (zone[gy][gx] === 0) right_blank.push(gx);\r\n                }\r\n                if (right_blank.length > 0) middle_data.push([gy, right_blank]);\r\n            }\r\n            let region_right_mid = get_region_info_v(middle_data, '右中', middle_gy);\r\n\r\n            let left_middle_data = [];\r\n            for (let gy = startGy; gy <= endGy; gy++) {\r\n                if (gy < tr2) continue;\r\n                let left_blank = [];\r\n                for (let gx = edge_margin_old; gx < cloth_center_gx; gx++) {\r\n                    if (zone[gy][gx] === 0) left_blank.push(gx);\r\n                }\r\n                if (left_blank.length > 0) left_middle_data.push([gy, left_blank]);\r\n            }\r\n            let region_left_mid = get_region_info_v(left_middle_data, '左中', middle_gy);\r\n\r\n            ctx.log('  区域格子数：');\r\n            ctx.log(`    左上: ${region0.count}个格子`);\r\n            ctx.log(`    右上: ${region1.count}个格子`);\r\n            ctx.log(`    左下: ${region2.count}个格子`);\r\n            ctx.log(`    右下: ${region3.count}个格子`);\r\n            ctx.log(`    下中: ${region_bottom_mid.count}个格子`);\r\n            ctx.log(`    右中: ${region_right_mid.count}个格子`);\r\n            ctx.log(`    左中: ${region_left_mid.count}个格子`);\r\n\r\n            if (n_sp === 4) {\r\n                selected_regions = [region0, region2, region1, region3];\r\n            } else if (n_sp === 3) {\r\n                let opt_a = [region0, region2, region_right_mid];\r\n                let opt_b = [region_left_mid, region1, region3];\r\n                let opt_c = [region1, region0, region_bottom_mid];\r\n                let score = rgs => rgs.reduce((sum, r) => sum + r.count, 0);\r\n                selected_regions = [opt_a, opt_b, opt_c].reduce((a, b) => score(a) > score(b) ? a : b);\r\n            } else if (n_sp === 2) {\r\n                let opt_a = [region0, region3];\r\n                let opt_b = [region2, region1];\r\n                let opt_c = [region0, region1];\r\n                let opt_d = [region2, region3];\r\n                let score = rgs => rgs.reduce((sum, r) => sum + r.count, 0);\r\n                selected_regions = [opt_a, opt_b, opt_c, opt_d].reduce((a, b) => score(a) > score(b) ? a : b);\r\n            } else if (n_sp === 1) {\r\n                let candidates = [region0, region2, region1, region3, region_bottom_mid];\r\n                selected_regions = [candidates.reduce((a, b) => a.count > b.count ? a : b)];\r\n            } else {\r\n                let all_regions = [region0, region2, region1, region3, region_bottom_mid, region_right_mid, region_left_mid];\r\n                selected_regions = all_regions.sort((a, b) => b.count - a.count).slice(0, n_sp);\r\n            }\r\n        }\r\n\r\n        let [rHsv, gHsv, bHsv] = avg_bg.map(x => x / 255.0);\r\n        let [hue, sat, val] = rgbToHsv(rHsv, gHsv, bHsv);\r\n        let base_region_colors = [];\r\n        for (let offset of [0, 0.08, -0.08, 0.5, 0.25, -0.15]) {\r\n            let h2 = (hue + offset) % 1.0;\r\n            let s2 = Math.max(0.25, Math.min(0.55, sat * 0.7));\r\n            let v2 = is_dark ? 0.75 : 0.60;\r\n            let [rr, gg2, bb] = hsvToRgb(h2, s2, v2);\r\n            base_region_colors.push([rr, gg2, bb, 255]);\r\n        }\r\n        if (sat < 0.15 && val > 0.8) {\r\n            base_region_colors = [[70, 75, 85, 255], [100, 80, 65, 255], [65, 85, 80, 255], [85, 70, 90, 255], [90, 60, 60, 255], [75, 90, 70, 255]];\r\n        }\r\n\r\n        let region_color_map = {\r\n            '左上': base_region_colors[0], '右上': base_region_colors[1],\r\n            '左下': base_region_colors[2], '右下': base_region_colors[3],\r\n            '下中': base_region_colors[4], '右中': base_region_colors[1],\r\n            '左中': base_region_colors[5],\r\n            '右侧1': base_region_colors[0], '右侧2': base_region_colors[1],\r\n            '右侧3': base_region_colors[2], '右侧4': base_region_colors[3],\r\n            '左侧1': base_region_colors[0], '左侧2': base_region_colors[1],\r\n            '左侧3': base_region_colors[2], '左侧4': base_region_colors[3],\r\n            '默认': base_region_colors[0]\r\n        };\r\n\r\n        for (let reg of selected_regions) {\r\n            reg.color = region_color_map[reg.name] || base_region_colors[0];\r\n        }\r\n\r\n        let cwp = w / COLS;\r\n        let chp = h / ROWS;\r\n\r\n        let fs2 = Math.floor(Math.min(w, h) * 0.025);\r\n        fs2 = Math.max(24, Math.min(fs2, 120)) + 5;\r\n\r\n        let rawTitle = titleLines.filter(x => x).join(' ');\r\n        // AI 精简优先（用户要求：标题用 AI 精简，而不是机械截断）\r\n        let simplified = (await aiCompactTitle(rawTitle, 60)) || await compactProductTitle(rawTitle, 50);\r\n        let full_title = simplified.en;\r\n        ctx.log(`  原标题: ${rawTitle}`);\r\n        ctx.log(`  简化后: ${full_title}`);\r\n        if (simplified.cn) ctx.log(`  中文翻译: ${simplified.cn}`);\r\n\r\n        let total_chars = full_title.replace(/\\s/g, '').length;\r\n        let words = full_title.split(' ');\r\n        let n_words = words.length;\r\n\r\n        let n_lines;\r\n        if (total_chars <= 18 || n_words === 1) {\r\n            n_lines = 1;\r\n        } else {\r\n            n_lines = 2;\r\n        }\r\n\r\n        let lines;\r\n        if (n_lines === 1) {\r\n            lines = [full_title];\r\n        } else if (n_words === 2) {\r\n            lines = [words[0], words[1]];\r\n        } else {\r\n            let target = total_chars / 2;\r\n            let cum = 0;\r\n            let split_idx = Math.floor(n_words / 2);\r\n            let best_diff = Infinity;\r\n            for (let i = 1; i < n_words; i++) {\r\n                cum += words[i - 1].length;\r\n                let diff = Math.abs(cum - target);\r\n                if (diff < best_diff) {\r\n                    best_diff = diff;\r\n                    split_idx = i;\r\n                }\r\n            }\r\n            split_idx = Math.max(1, Math.min(split_idx, n_words - 1));\r\n            lines = [words.slice(0, split_idx).join(' '), words.slice(split_idx).join(' ')];\r\n        }\r\n\r\n        lines = lines.filter(l => l && l.trim());\r\n        let n = lines.length;\r\n        let ah = tr2 * (h / ROWS);\r\n\r\n        let titleColor = is_dark ? '#ffffff' : '#282832';\r\n        let fs = Math.floor(ah * 0.35);\r\n        fs = Math.max(24, Math.min(fs, 110));\r\n        g.font = `bold ${fs}px Arial, sans-serif`;\r\n\r\n        while (Math.max(...lines.map(l => getTextWidth(g, l))) > w - 30 && fs > 14) {\r\n            fs -= 2;\r\n            g.font = `bold ${fs}px Arial, sans-serif`;\r\n        }\r\n\r\n        let lh = fs + Math.max(4, Math.floor(fs / 6));\r\n        while (n * lh > ah - 10 && fs > 14) {\r\n            fs -= 2;\r\n            g.font = `bold ${fs}px Arial, sans-serif`;\r\n            lh = fs + Math.max(4, Math.floor(fs / 6));\r\n        }\r\n\r\n        if (fs <= fs2) {\r\n            ctx.log(`  标题字号(${fs}px)小于等于标注字号(${fs2}px)，不显示标题`);\r\n        } else {\r\n            lh = fs + Math.max(4, Math.floor(fs / 6));\r\n            let th2 = n * lh;\r\n            let sy = Math.floor((ah - th2) / 2);\r\n            g.fillStyle = titleColor;\r\n            g.textBaseline = 'top';\r\n            for (let i = 0; i < lines.length; i++) {\r\n                let lw = getTextWidth(g, lines[i]);\r\n                let lx = Math.floor((w - lw) / 2);\r\n                g.fillText(lines[i], lx, sy + i * lh);\r\n            }\r\n            ctx.log(`  标题 ${n}行 (共${total_chars}字符) 字号:${fs}px 颜色:${titleColor} -> [${lines.join(', ')}]`);\r\n        }\r\n\r\n        let selling_sorted = [...sellingPoints].sort((a, b) => b.length - a.length);\r\n        let regions_sorted = selected_regions.map((r, i) => ({ r, i })).sort((a, b) => b.r.count - a.r.count);\r\n\r\n        let assignments = [];\r\n        for (let i = 0; i < regions_sorted.length && i < selling_sorted.length; i++) {\r\n            assignments.push([regions_sorted[i].r, selling_sorted[i]]);\r\n        }\r\n\r\n        g.font = `${fs2}px Arial, sans-serif`;\r\n\r\n        function capsulePath(g, bx_, by_, pw_, ph_, r_) {\r\n            // 四角圆角矩形，与 Python ImageDraw.rounded_rectangle 语义一致\r\n            g.beginPath();\r\n            g.moveTo(bx_ + r_, by_);\r\n            g.lineTo(bx_ + pw_ - r_, by_);\r\n            g.arcTo(bx_ + pw_, by_, bx_ + pw_, by_ + r_, r_);\r\n            g.lineTo(bx_ + pw_, by_ + ph_ - r_);\r\n            g.arcTo(bx_ + pw_, by_ + ph_, bx_ + pw_ - r_, by_ + ph_, r_);\r\n            g.lineTo(bx_ + r_, by_ + ph_);\r\n            g.arcTo(bx_, by_ + ph_, bx_, by_ + ph_ - r_, r_);\r\n            g.lineTo(bx_, by_ + r_);\r\n            g.arcTo(bx_, by_, bx_ + r_, by_, r_);\r\n            g.closePath();\r\n        }\r\n\r\n        for (let [region, text] of assignments) {\r\n            let gy_center = region.gy_center;\r\n            let gxs = region.gxs;\r\n            if (!gxs || gxs.length === 0) continue;\r\n\r\n            let full_data = region.full_data || [];\r\n            let orient = region.orient || 'v';\r\n            let row_gxs = null;\r\n\r\n            if (orient === 'v') {\r\n                for (let [g, row] of full_data) {\r\n                    if (g === gy_center) {\r\n                        row_gxs = row;\r\n                        break;\r\n                    }\r\n                }\r\n                if (row_gxs === null && full_data.length > 0) {\r\n                    row_gxs = full_data.reduce((a, b) => Math.abs(a[0] - gy_center) < Math.abs(b[0] - gy_center) ? a : b)[1];\r\n                }\r\n            } else {\r\n                row_gxs = full_data.filter(([gx, gys]) => gys.includes(gy_center)).map(([gx]) => gx);\r\n            }\r\n\r\n            if (!row_gxs) row_gxs = [...gxs];\r\n            row_gxs.sort((a, b) => a - b);\r\n\r\n            let gx_min = row_gxs[0];\r\n            let gx_max = row_gxs[row_gxs.length - 1];\r\n            let rx1 = Math.floor(gx_min * cwp);\r\n            let rx2 = Math.floor((gx_max + 1) * cwp);\r\n            let reg_gy_min = region.gy_min != null ? region.gy_min : Math.max(0, Math.floor(gy_center) - 3);\r\n            let reg_gy_max = region.gy_max != null ? region.gy_max : Math.min(ROWS - 1, Math.floor(gy_center) + 3);\r\n            let ry1 = Math.floor(reg_gy_min * chp);\r\n            let ry2 = Math.floor((reg_gy_max + 1) * chp);\r\n            let center_x = Math.floor((rx1 + rx2) / 2);\r\n\r\n            let parts = text.split(/[,，\\n;；]/).map(p => p.trim()).filter(p => p);\r\n            let seen = new Set();\r\n            let raw_lines = [];\r\n            for (let part of parts) {\r\n                if (!seen.has(part)) {\r\n                    seen.add(part);\r\n                    raw_lines.push(part);\r\n                }\r\n            }\r\n\r\n            let region_w = rx2 - rx1;\r\n            let cap_bw = Math.floor(region_w * 0.9);\r\n            let cap_text_w = Math.max(fs2 * 6, cap_bw - 50);\r\n\r\n            let text_lines = [];\r\n            for (let raw_ln of raw_lines) {\r\n                let ln_w = getTextWidth(g, raw_ln);\r\n                if (ln_w <= cap_text_w) {\r\n                    text_lines.push(raw_ln);\r\n                } else {\r\n                    let text_words = raw_ln.split(' ');\r\n                    let current = '';\r\n                    for (let word of text_words) {\r\n                        let trial = current ? current + ' ' + word : word;\r\n                        let trial_w = getTextWidth(g, trial);\r\n                        if (trial_w <= cap_text_w) {\r\n                            current = trial;\r\n                        } else {\r\n                            if (current) text_lines.push(current);\r\n                            current = word;\r\n                        }\r\n                    }\r\n                    if (current) text_lines.push(current);\r\n                }\r\n            }\r\n\r\n            if (text_lines.length > 5) {\r\n                let rest = text_lines.slice(4).join(' ');\r\n                text_lines = text_lines.slice(0, 4).concat([rest]);\r\n            }\r\n\r\n            let num_lines = text_lines.length;\r\n            let max_tw = Math.max(...text_lines.map(ln => getTextWidth(g, ln)));\r\n            let line_gap = Math.floor(fs2 / 3);\r\n            let bh_mult;\r\n            if (num_lines === 1) {\r\n                bh_mult = 2;\r\n            } else if (num_lines === 2) {\r\n                bh_mult = 1.3;\r\n            } else {\r\n                bh_mult = 1.1;\r\n            }\r\n\r\n            let px_bw = Math.floor(max_tw + 60);\r\n            let px_bh = Math.floor((num_lines * fs2 + (num_lines - 1) * line_gap) * bh_mult);\r\n\r\n            px_bw = Math.floor(px_bw * 1.1);\r\n            px_bh = Math.floor(px_bh * 1.1);\r\n\r\n            let img_center_x = Math.floor(w / 2);\r\n            let region_center_x = Math.floor((rx1 + rx2) / 2);\r\n            let region_center_y = Math.floor((ry1 + ry2) / 2);\r\n\r\n            let bx, by;\r\n            if (num_lines === 1) {\r\n                region_w = rx2 - rx1;\r\n                let new_cx;\r\n                if (region_center_x < img_center_x) {\r\n                    new_cx = rx2 - Math.floor(region_w / 3);\r\n                } else {\r\n                    new_cx = rx1 + Math.floor(region_w / 3);\r\n                }\r\n                let dist = region_center_x < img_center_x ? (rx2 - new_cx) : (new_cx - rx1);\r\n                ctx.log(`  [debug] ${region.name}: 区域宽=${region_w}px, 新cx=${new_cx}, 中心(cx)距离衣服端: ${dist}px`);\r\n                bx = new_cx - Math.floor(px_bw / 2);\r\n                by = region_center_y - Math.floor(px_bh / 2);\r\n            } else {\r\n                bx = center_x - Math.floor(px_bw / 2);\r\n                by = region_center_y - Math.floor(px_bh / 2);\r\n            }\r\n\r\n            bx = Math.max(5, Math.min(w - px_bw - 5, bx));\r\n            by = Math.max(5, Math.min(h - px_bh - 5, by));\r\n\r\n            let r2 = Math.min(Math.floor(px_bh / 2), 50);\r\n\r\n            let blurPad = 20;\r\n            let cropX = Math.max(0, bx - blurPad);\r\n            let cropY = Math.max(0, by - blurPad);\r\n            let cropW = Math.min(w - cropX, px_bw + blurPad * 2);\r\n            let cropH = Math.min(h - cropY, px_bh + blurPad * 2);\r\n\r\n            let cropCanvas = document.createElement('canvas');\r\n            cropCanvas.width = cropW;\r\n            cropCanvas.height = cropH;\r\n            let cropCtx = cropCanvas.getContext('2d');\r\n            cropCtx.drawImage(canvas, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH);\r\n            cropCtx.filter = 'blur(8px)';\r\n            cropCtx.drawImage(cropCanvas, 0, 0);\r\n            cropCtx.filter = 'none';\r\n\r\n            let maskCanvas2 = document.createElement('canvas');\r\n            maskCanvas2.width = w;\r\n            maskCanvas2.height = h;\r\n            let maskCtx2 = maskCanvas2.getContext('2d');\r\n            capsulePath(maskCtx2, bx, by, px_bw, px_bh, r2);\r\n            maskCtx2.fillStyle = '#ffffff';\r\n            maskCtx2.fill();\r\n\r\n            let frostedCanvas = document.createElement('canvas');\r\n            frostedCanvas.width = w;\r\n            frostedCanvas.height = h;\r\n            let frostedCtx = frostedCanvas.getContext('2d');\r\n            frostedCtx.drawImage(cropCanvas, cropX, cropY);\r\n            frostedCtx.globalCompositeOperation = 'destination-in';\r\n            frostedCtx.drawImage(maskCanvas2, 0, 0);\r\n            frostedCtx.globalCompositeOperation = 'source-over';\r\n\r\n            g.globalAlpha = 0.75;\r\n            g.drawImage(frostedCanvas, 0, 0);\r\n            g.globalAlpha = 1.0;\r\n\r\n            capsulePath(g, bx, by, px_bw, px_bh, r2);\r\n            g.fillStyle = 'rgba(255, 255, 255, 0.18)';\r\n            g.fill();\r\n\r\n            g.save();\r\n            capsulePath(g, bx, by, px_bw, px_bh, r2);\r\n            g.clip();\r\n            for (let gy = 0; gy < px_bh; gy++) {\r\n                let alpha = Math.floor(50 * Math.max(0, 1 - (gy / px_bh) * 2));\r\n                g.fillStyle = `rgba(255, 255, 255, ${alpha / 255})`;\r\n                g.fillRect(bx, by + gy, px_bw, 1);\r\n            }\r\n            g.restore();\r\n\r\n            capsulePath(g, bx, by, px_bw, px_bh, r2);\r\n            g.strokeStyle = 'rgba(255, 255, 255, 0.78)';\r\n            g.lineWidth = 3;\r\n            g.stroke();\r\n\r\n            let r3 = r2 + 4;\r\n            capsulePath(g, bx - 4, by - 4, px_bw + 8, px_bh + 8, r3);\r\n            g.strokeStyle = `rgba(${avg_bg[0]}, ${avg_bg[1]}, ${avg_bg[2]}, 0.78)`;\r\n            g.lineWidth = 3;\r\n            g.stroke();\r\n\r\n            g.save();\r\n            capsulePath(g, bx, by, px_bw, px_bh, r2);\r\n            g.clip();\r\n            let rInner = Math.max(0, r2 - 2);\r\n            capsulePath(g, bx + 2, by + 2, px_bw - 4, px_bh - 4, rInner);\r\n            g.strokeStyle = 'rgba(255, 255, 255, 0.31)';\r\n            g.lineWidth = 1;\r\n            g.stroke();\r\n            g.restore();\r\n\r\n            g.font = `${fs2}px Arial, sans-serif`;\r\n            g.textAlign = 'center';\r\n            g.textBaseline = 'middle';\r\n            g.fillStyle = '#141414';\r\n\r\n            let total_h = num_lines * fs2 + (num_lines - 1) * line_gap;\r\n            let start_y = by + Math.floor((px_bh - total_h) / 2);\r\n\r\n            for (let i = 0; i < num_lines; i++) {\r\n                let ly = start_y + i * (fs2 + line_gap) + Math.floor(fs2 / 2);\r\n                g.fillText(text_lines[i], bx + Math.floor(px_bw / 2), ly);\r\n            }\r\n\r\n            ctx.log(`  放置 ${text} 在 ${region.name} (${num_lines}行, 胶囊${px_bw}x${px_bh}px)`);\r\n        }\r\n    }\r\n\r\n    brandBlacklistData = await ctx.assets.readJson('brand_blacklist.json');\r\n\r\n    // 传 g（画布上下文）而非 ctx（SDK 上下文），避免函数内 ctx.log 被遮蔽\r\n    await annotateImageOnCanvas(canvas, g, img, titleLines, sellingPoints);\r\n    ctx.log('  OK 111标注完成');\r\n}, {\r\n  timeoutMs: 120000,\r\n  preserveLegacySignals: true,\r\n});\r\n","111扩图.js":"/**\n * 111扩图 — SDK v2.2 + @contract\n *\n * @contract\n * @needs canvas:main\n * @supports single\n * @fallback alert\n * @timeout 120000\n *\n * 自动检测衣服区域，四周留白不足时扩图/缩图\n * 对齐 Python 扩图工具.py 逻辑，使用 ONNX rembg + Canvas API\n * ONNX session 通过 window 全局缓存跨脚本/跨注入复用（对齐 111卖点图后处理.js）\n */\nCustomJsSDK.run(async ctx => {\n  const { canvas, ctx: g, img } = ctx;\n\n  const TRIGGER_HIGH = 0.26;\n  const TARGET = 0.24;\n  const w0 = img.width;\n  const h0 = img.height;\n\n  ctx.log('[扩缩图] 原图尺寸: ' + w0 + 'x' + h0);\n\n  // ============================================================\n  // 抠图 / 网格分析：共享实现，见 SDK 的 ctx.rembg\n  //   111卖点图 / 111扩图 / 444扩图 三份实现实测逻辑一致（仅注释与 const/let 风格不同），\n  //   集中到 SDK 后 session 缓存键、320×320 归一化、LANCZOS 回缩放等细节只维护一处。\n  //   注意：sampleBgColor 与接缝混合**不在共享范围**（三份签名/算法不同，非重复实现）。\n  // ============================================================\n  const { getOrCreateU2NetSession, rembgRemoveBackground, gridAnalysis } = ctx.rembg;\n\n  // ============================================================\n  // 1. rembg 抠图 → alpha mask —— 已移到共享实现（见上方 ctx.rembg 解构）\n  // ============================================================\n\n  // ============================================================\n  // 2. 网格分析与衣服检测 —— 已移到共享实现（ctx.rembg.gridAnalysis）\n  // ============================================================\n\n  // ============================================================\n  // 3. 背景色采样\n  // ============================================================\n  function sampleBgColor(origCanvas, alphaCanvas) {\n    const w = origCanvas.width, h = origCanvas.height;\n    const oCtx = origCanvas.getContext('2d');\n    const oData = oCtx.getImageData(0, 0, w, h).data;\n    const aData = alphaCanvas.getContext('2d').getImageData(0, 0, w, h).data;\n\n    let rSum = 0, gSum = 0, bSum = 0, count = 0;\n    for (let i = 0; i < aData.length; i += 4) {\n      if (aData[i] < 13) { // alpha < 5% (≈ 13/255)\n        rSum += oData[i];\n        gSum += oData[i + 1];\n        bSum += oData[i + 2];\n        count++;\n      }\n    }\n    if (count > 0) return [Math.round(rSum / count), Math.round(gSum / count), Math.round(bSum / count)];\n    return [240, 240, 240];\n  }\n\n  // ============================================================\n  // 4. 接缝模糊混合（cosine-weighted band blur）\n  //\n  // ⚠️ 与 444扩图.js 的 `blendSeams(newCanvas, origImg, x, y)` **不是同一个函数**：\n  //    本函数按「轴向 + 缝位置」作用在已有画布上（targetCanvas, origW, origH, offsetX, offsetY），\n  //    444 那份是「双向渐变 + 高斯模糊带」且入参是原图 Image。两者算法与签名都不同，\n  //    **不属重复实现，禁止合并**（合并会改变出图结果）。命名相似纯属历史巧合。\n  // ============================================================\n  function blendSeamBands(targetCanvas, origW, origH, offsetX, offsetY) {\n    const nc = targetCanvas.getContext('2d');\n    const w = targetCanvas.width, h = targetCanvas.height;\n    const blurPct = 0.05;\n\n    function blurBand(axis, seam) {\n      const bw = Math.max(1, Math.round(Math.max(w, h) * blurPct));\n      const maxAxis = axis === 0 ? h : w;\n      const b0 = Math.max(0, seam - bw);\n      const b1 = Math.min(maxAxis, seam + bw);\n      if (b1 <= b0) return;\n\n      const sx = axis === 0 ? 0 : b0;\n      const sy = axis === 0 ? b0 : 0;\n      const sw = axis === 0 ? w : b1 - b0;\n      const sh = axis === 0 ? b1 - b0 : h;\n\n      // 对整张图做模糊，只取接缝带部分\n      const temp = document.createElement('canvas');\n      temp.width = w;\n      temp.height = h;\n      const tc = temp.getContext('2d');\n      tc.filter = `blur(${Math.max(3, bw)}px)`;\n      tc.drawImage(targetCanvas, 0, 0);\n\n      // 提取模糊带和原图带\n      const origBand = nc.getImageData(sx, sy, sw, sh);\n      const blurBand = tc.getImageData(sx, sy, sw, sh);\n      const outData = nc.createImageData(sw, sh);\n      const len = sw * sh;\n\n      for (let i = 0; i < len; i++) {\n        const coord = axis === 0 ? Math.floor(i / sw) + sy : (i % sw) + sx;\n        let dist = Math.abs(coord - seam) / bw;\n        if (dist > 1) dist = 1;\n        const t = 0.5 + 0.5 * Math.cos(dist * Math.PI); // cosine ease\n        const j = i * 4;\n        outData.data[j]   = origBand.data[j]   * (1 - t) + blurBand.data[j]   * t;\n        outData.data[j+1] = origBand.data[j+1] * (1 - t) + blurBand.data[j+1] * t;\n        outData.data[j+2] = origBand.data[j+2] * (1 - t) + blurBand.data[j+2] * t;\n        outData.data[j+3] = 255;\n      }\n      nc.putImageData(outData, sx, sy);\n    }\n\n    // 上接缝\n    if (offsetY > 0) blurBand(0, offsetY);\n    // 下接缝\n    if (offsetY + origH < h) blurBand(0, offsetY + origH);\n    // 左接缝\n    if (offsetX > 0) blurBand(1, offsetX);\n    // 右接缝\n    if (offsetX + origW < w) blurBand(1, offsetX + origW);\n  }\n\n  // ============================================================\n  // 5. 主流程\n  // ============================================================\n  ctx.log('[扩缩图] 开始 rembg 抠图...');\n  const alphaCanvas = await rembgRemoveBackground(img);\n  ctx.log('[扩缩图] rembg 完成');\n\n  const { clothCells, cellRatio, bbox } = gridAnalysis(alphaCanvas);\n  ctx.log('[扩缩图] 格子占比: ' + (cellRatio * 100).toFixed(1) + '% 衣服格子: ' + clothCells + ' bbox: ' + bbox);\n\n  if (bbox === null) {\n    ctx.log('[扩缩图] 未检测到衣服，不调整');\n    return;\n  }\n\n  if (cellRatio <= TRIGGER_HIGH && cellRatio >= TARGET) {\n    ctx.log('[扩缩图] 在范围内 (' + (TARGET*100).toFixed(0) + '%~' + (TRIGGER_HIGH*100).toFixed(0) + '%)，不调整');\n    return;\n  }\n\n  const scale = Math.sqrt(cellRatio / TARGET);\n  const newW = Math.round(w0 * scale);\n  const newH = Math.round(h0 * scale);\n  const offsetX = Math.floor((newW - w0) / 2);\n  const offsetY = Math.floor((newH - h0) / 2);\n\n  if (cellRatio < TARGET) {\n    // 缩图：裁剪中心区域\n    ctx.log('[扩缩图] 缩小画布: ' + w0 + 'x' + h0 + ' → ' + newW + 'x' + newH);\n    const cropX = Math.floor((w0 - newW) / 2);\n    const cropY = Math.floor((h0 - newH) / 2);\n\n    const newCanvas = document.createElement('canvas');\n    newCanvas.width = newW;\n    newCanvas.height = newH;\n    const nc2 = newCanvas.getContext('2d');\n    nc2.drawImage(img, cropX, cropY, newW, newH, 0, 0, newW, newH);\n\n    // 替换原 canvas\n    canvas.width = newW;\n    canvas.height = newH;\n    g.drawImage(newCanvas, 0, 0);\n  } else {\n    // 扩图：扩大画布，原图居中\n    // 注：expandBot = newH - h0 - offsetY（下方扩展量），expandRight = newW - w0 - offsetX（右方扩展量）\n    const expandTop = offsetY;\n    const expandBot = newH - h0 - offsetY;\n    const expandLeft = offsetX;\n    const expandRight = newW - w0 - offsetX;\n    ctx.log('[扩缩图] 扩大画布: ' + w0 + 'x' + h0 + ' → ' + newW + 'x' + newH +\n            ' 各方向: 上' + expandTop + ' 下' + expandBot + ' 左' + expandLeft + ' 右' + expandRight);\n\n    // 采样背景色\n    const bgColor = sampleBgColor(canvas, alphaCanvas);\n    ctx.log('[扩缩图] 背景色: RGB(' + bgColor.join(',') + ')');\n\n    // 创建新画布\n    const newCanvas = document.createElement('canvas');\n    newCanvas.width = newW;\n    newCanvas.height = newH;\n    const nc2 = newCanvas.getContext('2d');\n\n    // 填充背景色\n    nc2.fillStyle = 'rgb(' + bgColor.join(',') + ')';\n    nc2.fillRect(0, 0, newW, newH);\n\n    // 画原图居中\n    nc2.drawImage(img, offsetX, offsetY);\n\n    // 接缝模糊\n    blendSeamBands(newCanvas, w0, h0, offsetX, offsetY);\n\n    // 替换原 canvas\n    canvas.width = newW;\n    canvas.height = newH;\n    g.drawImage(newCanvas, 0, 0);\n  }\n\n  ctx.log('[扩缩图] 完成');\n}, {\n  timeoutMs: 120000,\n  preserveLegacySignals: true,\n});\n","222细节图后处理.js":"/**\n * 222 袖口细节图后处理脚本 — SDK v2.2 + @contract\n *\n * @contract\n * @needs canvas:main\n * @needs row:product\n * @supports single\n * @fallback alert\n * @timeout 120000\n *\n * @resource productRow row \"当前产品行（Excel）\" from:currentSet.row\n *\n * 数据来源：ctx.data.excelRow —— 当前导入 Excel 的当前产品行快照，按真实 Excel 列名取值。\n * 袖列随类目变化，统一由 CategoryFieldRules 的 sleeve 角色解析：\n *   polo / t-shirt → 袖子款式；shirt → 袖长(cm)；帽衫 / 无帽卫衣 → 袖型。\n *\n * 完全对齐 Python image_review_regen_gui.py 的 _draw_detail_text_on_image 实现。\n * 移植自 L143-358（_get_detail_text_content + _draw_detail_text_on_image + _analyze_image_color）。\n */\nCustomJsSDK.run(async ctx => {\n  const { canvas, ctx: g } = ctx;\n  // 当前产品行快照；缺失即报错，不静默回退到空值\n  if (!ctx.data.excelRow) throw new Error('缺少当前产品行数据（excelRow）');\n\n  // ============================================================\n  // 常量（移植自 L114-129）\n  // ============================================================\n  // ============================================================\n  // 工具函数 —— 共享实现放在 SDK 的 ctx.draw（单一真源），本脚本只做绑定与适配\n  //\n  // 此前 222/333/666 各自内联同一套 5 个绘制函数 + tagList（共约 300 行重复），\n  // 且已出现漂移（标题断行正则只在 333 修过、变量名 t/tt 不一致）。\n  // 现统一由 ctx.draw 提供，调用点写法保持不变。\n  // ============================================================\n  const { rgbToHsv, hsvToRgb, cleanText, sameDisplayText, tagList, splitPctLines } = ctx.draw;\n\n  /** _clean：空值/none/n/a 归一为空字符串 */\n  const _clean = (val) => (!val || ['none', 'n/a', 'na'].includes(val.toLowerCase())) ? '' : val;\n\n  /** _v：按真实 Excel 列名取值 */\n  const _v = (column) => _clean(ctx.data.cell(column));\n\n  /** 绑定本脚本的 2D 上下文 g（调用点不变） */\n  function drawTextWithStroke(text, x, y, fillColor, strokeColor, offset) {\n    ctx.draw.drawTextWithStroke(g, text, x, y, fillColor, strokeColor, offset);\n  }\n\n  function drawRoundedRect(x, y, w, h, r) {\n    ctx.draw.drawRoundedRect(g, x, y, w, h, r);\n  }\n\n  // ============================================================\n  // 读取属性（移植自 L423-436）\n  // ============================================================\n  const craft = _v('工艺');\n  // 袖列随类目变化，由 CategoryFieldRules 的 sleeve 角色解析成真实列名：\n  //   shirt → 袖长(cm)；帽衫/无帽卫衣 → 袖型；polo / t-shirt → 袖子款式\n  const sleeveLength = _clean(ctx.data.role('sleeve').value);\n  const groupVal = ctx.data.category();\n\n  // ============================================================\n  // 颜色分析（移植自 _analyze_image_color L78-110）\n  // ============================================================\n  const W = canvas.width;\n  const H = canvas.height;\n  let rs = 0, gs = 0, bs = 0, ct = 0;\n  try {\n    const imageData = g.getImageData(0, 0, W, H);\n    const data = imageData.data;\n    for (let y = 0; y < H; y += 10) {\n      for (let x = 0; x < W; x += 10) {\n        const idx = (y * W + x) * 4;\n        const r = data[idx], g2 = data[idx + 1], b = data[idx + 2];\n        const lum = r * 299 + g2 * 587 + b * 114;\n        if (lum < 600000 && lum > 30000) {\n          rs += r; gs += g2; bs += b; ct++;\n        }\n      }\n    }\n  } catch (e) { /* 跨域等异常，降级使用默认色 */ }\n\n  let titleColor, titleStrokeRgba, accentColor, accentRgbSum;\n  let badgeBgRgba;\n\n  if (ct > 0) {\n    const avgR = Math.floor(rs / ct);\n    const avgG = Math.floor(gs / ct);\n    const avgB = Math.floor(bs / ct);\n    const brightness = Math.floor((avgR * 299 + avgG * 587 + avgB * 114) / 1000);\n    if (brightness > 150) {\n      titleColor = 'rgb(40, 40, 50)';\n      titleStrokeRgba = 'rgba(255, 255, 255, 0.39)';\n    } else {\n      titleColor = 'rgb(255, 255, 255)';\n      titleStrokeRgba = 'rgba(0, 0, 0, 0.39)';\n    }\n    const [h, s, v] = rgbToHsv(avgR, avgG, avgB);\n    // accent_color：相邻色（色相+0.1）\n    const h2 = (h + 0.1) % 1.0;\n    const s2 = Math.min(1.0, s * 1.5);\n    const v2 = brightness > 150 ? 0.4 : 0.7;\n    const [ar, ag, ab] = hsvToRgb(h2, s2, v2);\n    accentColor = `rgb(${ar}, ${ag}, ${ab})`;\n    accentRgbSum = ar + ag + ab;\n    // badge_bg：互补色（色相+0.5）\n    const h3 = (h + 0.5) % 1.0;\n    const s3 = Math.max(0.3, Math.min(0.6, s * 1.2));\n    const v3 = v < 0.5 ? 0.75 : 0.35;\n    const [br, bg, bb] = hsvToRgb(h3, s3, v3);\n    badgeBgRgba = `rgba(${br}, ${bg}, ${bb}, 0.9)`;\n  } else {\n    titleColor = 'rgb(40, 40, 50)';\n    titleStrokeRgba = 'rgba(255, 255, 255, 0.39)';\n    accentColor = 'rgb(120, 120, 120)';\n    accentRgbSum = 360;\n    badgeBgRgba = 'rgba(60, 65, 75, 0.9)';\n  }\n\n  // ============================================================\n  // 文字内容生成（移植自 _get_detail_text_content L182-195）\n  // ============================================================\n  let title = craft || sleeveLength;\n  if (!title) throw new Error('缺少工艺和袖型属性，无法标注袖口图');\n  const isShirt = groupVal === 'shirt';\n  const allTags = isShirt ? tagList(craft, sleeveLength) : tagList(craft);\n  let tags, subtitle;\n  if (allTags.length > 0) {\n    tags = allTags[0];\n    subtitle = '';\n  } else {\n    tags = '';\n    subtitle = '';\n  }\n  const badge = '';\n  const badgePos = 'br';\n\n  // cleanText 清理（移植自 L219-222）\n  title = cleanText(title);\n  subtitle = cleanText(subtitle);\n  tags = cleanText(tags);\n  if (sameDisplayText(tags, title)) tags = '';\n\n  // ============================================================\n  // 绘制（移植自 _draw_detail_text_on_image L248-358）\n  // ============================================================\n  const SEPARATOR = ' ';\n  g.textAlign = 'center';\n  g.textBaseline = 'top';\n\n  // --- 大标题 ---\n  const fsTitle = Math.floor(H * 0.07);\n  let currentFsTitle = fsTitle;\n  g.font = `bold ${fsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n  const maxW = Math.floor(W * 0.88);\n\n  // 标题换行：\\n → 百分比拆分 → 空格二分（移植自 L258-276）\n  let titleLines;\n  if (title.includes('\\n')) {\n    titleLines = title.split('\\n');\n  } else {\n    const titleWidth = g.measureText(title).width;\n    if (titleWidth > maxW) {\n      // 百分比拆分：95%Cotton 5%Elastane\n      const pctParts = splitPctLines(title);\n      if (pctParts.length > 1) {\n        titleLines = pctParts;\n        currentFsTitle = Math.floor(H * 0.055);\n        g.font = `bold ${currentFsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n      } else {\n        const words = title.split(' ');\n        const mid = Math.floor(words.length / 2);\n        titleLines = [words.slice(0, mid).join(' '), words.slice(mid).join(' ')];\n        currentFsTitle = Math.floor(H * 0.055);\n        g.font = `bold ${currentFsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n      }\n    } else {\n      titleLines = [title];\n    }\n  }\n\n  const ty = Math.floor(H * 0.06);\n  for (let i = 0; i < titleLines.length; i++) {\n    const ly = ty + i * Math.floor(currentFsTitle * 1.3);\n    drawTextWithStroke(titleLines[i], W / 2, ly, titleColor, titleStrokeRgba, 5);\n  }\n\n  // --- 副标题 ---\n  const fsSub = Math.floor(H * 0.05);\n  g.font = `bold ${fsSub}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n  const sy = ty + titleLines.length * Math.floor(currentFsTitle * 1.3) + Math.floor(currentFsTitle * 0.3);\n\n  if (subtitle) {\n    // stroke 基准改用 accentColor（移植自 L293-294）\n    const subStroke = accentRgbSum > 382 ? 'rgba(0, 0, 0, 0.39)' : 'rgba(255, 255, 255, 0.47)';\n    drawTextWithStroke(subtitle, W / 2, sy, accentColor, subStroke, 3);\n  }\n\n  // --- 标签行 ---\n  const fsTag = Math.floor(H * 0.03);\n  g.font = `bold ${fsTag}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n  const tagParts = tags ? tags.split(SEPARATOR).filter(p => p) : [];\n  const tagMaxW = Math.floor(W * 0.88);\n  const partWidths = tagParts.map(p => g.measureText(p).width);\n  const sepW = g.measureText(SEPARATOR).width;\n  const totalW = tagParts.length > 0\n    ? partWidths.reduce((a, b) => a + b, 0) + (tagParts.length - 1) * sepW\n    : 0;\n\n  // 标签换行（移植自 L308-317）\n  let tagLines;\n  if (totalW > tagMaxW && tagParts.length > 1) {\n    let bestMid = 1, bestDiff = 999999;\n    for (let mid = 1; mid < tagParts.length; mid++) {\n      const w1 = partWidths.slice(0, mid).reduce((a, b) => a + b, 0) + Math.max(0, mid - 1) * sepW;\n      const w2 = partWidths.slice(mid).reduce((a, b) => a + b, 0) + Math.max(0, tagParts.length - mid - 1) * sepW;\n      const diff = Math.abs(w1 - w2);\n      if (diff < bestDiff) { bestDiff = diff; bestMid = mid; }\n    }\n    tagLines = [\n      tagParts.slice(0, bestMid).join(SEPARATOR),\n      tagParts.slice(bestMid).join(SEPARATOR)\n    ];\n  } else {\n    tagLines = tags ? [tags] : [];\n  }\n\n  const tagY = sy + (subtitle ? Math.floor(fsSub * 1.8) : 0);\n  const tagStroke = accentRgbSum > 382 ? 'rgba(0, 0, 0, 0.39)' : 'rgba(255, 255, 255, 0.47)';\n\n  for (let li = 0; li < tagLines.length; li++) {\n    const line = tagLines[li];\n    const ly = tagY + li * Math.floor(fsTag * 1.8);\n    drawTextWithStroke(line, W / 2, ly, accentColor, tagStroke, 3);\n  }\n\n  // 222 无 badge\n\n  ctx.log('OK 222袖口标注完成');\n}, {\n  timeoutMs: 120000,\n  preserveLegacySignals: true,\n});\n","333面料图后处理.js":"/**\r\n * 333 面料细节图后处理脚本 — SDK v2.2 + @contract\r\n *\r\n * @contract\r\n * @needs canvas:main\r\n * @needs row:product\r\n * @supports single\r\n * @fallback alert\r\n * @timeout 120000\r\n *\r\n * @resource productRow row \"当前产品行（Excel）\" from:currentSet.row\r\n *\r\n * 数据来源：ctx.data.excelRow —— 当前导入 Excel 的当前产品行快照，按真实 Excel 列名取值。\r\n * 读取 材质 / 面料克重 / 产品特性 / 面料类型 / 图案类型 五列。\r\n * 注意：五个类目的克重列统一为「面料克重」、特性列统一为「产品特性」，\r\n *       旧脚本的 克重.txt / 特性.txt 别名已不再需要。\r\n *\r\n * 完全对齐 Python image_review_regen_gui.py 的 _draw_detail_text_on_image 实现。\r\n * 移植自 L143-358（_get_detail_text_content + _draw_detail_text_on_image + _analyze_image_color）。\r\n */\r\nCustomJsSDK.run(async ctx => {\r\n  const { canvas, ctx: g } = ctx;\r\n  // 当前产品行快照；缺失即报错，不静默回退到空值\r\n  if (!ctx.data.excelRow) throw new Error('缺少当前产品行数据（excelRow）');\r\n\r\n  // 只在原图上叠加文字，不改动画面：画布创建时已按原图尺寸绘制，这里不再重绘/裁剪/缩放。\r\n  if (!ctx.img) throw new Error('缺少面料图原始位图');\r\n\r\n  // ============================================================\r\n  // 工具函数 —— 共享实现放在 SDK 的 ctx.draw（单一真源），本脚本只做绑定与适配\r\n  //\r\n  // 此前 222/333/666 各自内联同一套 5 个绘制函数 + tagList（共约 300 行重复），\r\n  // 且已出现漂移（变量名 t/tt 不一致）。现统一由 ctx.draw 提供，调用点写法保持不变。\r\n  // ============================================================\r\n  const { rgbToHsv, hsvToRgb, cleanText, formatWeight, tagList, splitPctLines } = ctx.draw;\r\n\r\n  /** _clean：空值/none/n/a 归一为空字符串 */\r\n  const _clean = (val) => (!val || ['none', 'n/a', 'na'].includes(val.toLowerCase())) ? '' : val;\r\n\r\n  /** _v：按真实 Excel 列名取值 */\r\n  const _v = (column) => _clean(ctx.data.cell(column));\r\n\r\n  /** 绑定本脚本的 2D 上下文 g（调用点不变） */\r\n  function drawTextWithStroke(text, x, y, fillColor, strokeColor, offset) {\r\n    ctx.draw.drawTextWithStroke(g, text, x, y, fillColor, strokeColor, offset);\r\n  }\r\n\r\n  function drawRoundedRect(x, y, w, h, r) {\r\n    ctx.draw.drawRoundedRect(g, x, y, w, h, r);\r\n  }\r\n\r\n  // ============================================================\r\n  // 读取属性（移植自 L423-436）\r\n  // ============================================================\r\n  // 真实 Excel 列名；五个类目的克重列统一为「面料克重」、特性列统一为「产品特性」\r\n  const mat = _v('材质');\r\n  const weight = _v('面料克重');\r\n  const feat = _v('产品特性');\r\n  const fabricType = _v('面料类型');\r\n  const pattern = _v('图案类型');\r\n\r\n  // ============================================================\r\n  // 颜色分析（移植自 _analyze_image_color L78-110）\r\n  // ============================================================\r\n  const W = canvas.width;\r\n  const H = canvas.height;\r\n  let rs = 0, gs = 0, bs = 0, ct = 0;\r\n  try {\r\n    const imageData = g.getImageData(0, 0, W, H);\r\n    const data = imageData.data;\r\n    for (let y = 0; y < H; y += 10) {\r\n      for (let x = 0; x < W; x += 10) {\r\n        const idx = (y * W + x) * 4;\r\n        const r = data[idx], g2 = data[idx + 1], b = data[idx + 2];\r\n        const lum = r * 299 + g2 * 587 + b * 114;\r\n        if (lum < 600000 && lum > 30000) {\r\n          rs += r; gs += g2; bs += b; ct++;\r\n        }\r\n      }\r\n    }\r\n  } catch (e) { /* 跨域等异常，降级使用默认色 */ }\r\n\r\n  let titleColor, titleStrokeRgba, accentColor, accentRgbSum;\r\n  let badgeBgRgba;\r\n\r\n  if (ct > 0) {\r\n    const avgR = Math.floor(rs / ct);\r\n    const avgG = Math.floor(gs / ct);\r\n    const avgB = Math.floor(bs / ct);\r\n    const brightness = Math.floor((avgR * 299 + avgG * 587 + avgB * 114) / 1000);\r\n    if (brightness > 150) {\r\n      titleColor = 'rgb(40, 40, 50)';\r\n      titleStrokeRgba = 'rgba(255, 255, 255, 0.39)';\r\n    } else {\r\n      titleColor = 'rgb(255, 255, 255)';\r\n      titleStrokeRgba = 'rgba(0, 0, 0, 0.39)';\r\n    }\r\n    const [h, s, v] = rgbToHsv(avgR, avgG, avgB);\r\n    // accent_color：相邻色（色相+0.1）\r\n    const h2 = (h + 0.1) % 1.0;\r\n    const s2 = Math.min(1.0, s * 1.5);\r\n    const v2 = brightness > 150 ? 0.4 : 0.7;\r\n    const [ar, ag, ab] = hsvToRgb(h2, s2, v2);\r\n    accentColor = `rgb(${ar}, ${ag}, ${ab})`;\r\n    accentRgbSum = ar + ag + ab;\r\n    // badge_bg：互补色（色相+0.5）\r\n    const h3 = (h + 0.5) % 1.0;\r\n    const s3 = Math.max(0.3, Math.min(0.6, s * 1.2));\r\n    const v3 = v < 0.5 ? 0.75 : 0.35;\r\n    const [br, bg, bb] = hsvToRgb(h3, s3, v3);\r\n    badgeBgRgba = `rgba(${br}, ${bg}, ${bb}, 0.9)`;\r\n  } else {\r\n    titleColor = 'rgb(40, 40, 50)';\r\n    titleStrokeRgba = 'rgba(255, 255, 255, 0.39)';\r\n    accentColor = 'rgb(120, 120, 120)';\r\n    accentRgbSum = 360;\r\n    badgeBgRgba = 'rgba(60, 65, 75, 0.9)';\r\n  }\r\n\r\n  // ============================================================\r\n  // 文字内容生成（移植自 _get_detail_text_content L160-167）\r\n  // ============================================================\r\n  const displayWeight = formatWeight(weight);\r\n  let title = (displayWeight && mat) ? `${displayWeight} ${mat.toUpperCase()}` : (displayWeight || mat);\r\n  if (!title) throw new Error('缺少克重和材质属性，无法标注面料图');\r\n  const subtitle = '';\r\n  // 标签随机打乱取第一个（移植自 random.shuffle + [0]）\r\n  const allTags = tagList(fabricType, pattern, feat);\r\n  const shuffled = allTags.slice();\r\n  for (let i = shuffled.length - 1; i > 0; i--) {\r\n    const j = Math.floor(Math.random() * (i + 1));\r\n    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];\r\n  }\r\n  const tags = shuffled.length > 0 ? shuffled[0] : '';\r\n  const badge = '';\r\n  const badgePos = 'br';\r\n\r\n  // cleanText 清理\r\n  title = cleanText(title);\r\n  // subtitle 为空，跳过\r\n  // tags 已是单个字符串，cleanText 处理\r\n  const cleanedTags = cleanText(tags);\r\n\r\n  // ============================================================\r\n  // 绘制（移植自 _draw_detail_text_on_image L248-358）\r\n  // ============================================================\r\n  const SEPARATOR = ' ';\r\n  g.textAlign = 'center';\r\n  g.textBaseline = 'top';\r\n\r\n  // --- 大标题 ---\r\n  const fsTitle = Math.floor(H * 0.07);\r\n  let currentFsTitle = fsTitle;\r\n  g.font = `bold ${fsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\r\n  const maxW = Math.floor(W * 0.88);\r\n\r\n  // 标题换行：\\n → 百分比拆分 → 空格二分（移植自 L258-276）\r\n  let titleLines;\r\n  if (title.includes('\\n')) {\r\n    titleLines = title.split('\\n');\r\n  } else {\r\n    const titleWidth = g.measureText(title).width;\r\n    if (titleWidth > maxW) {\r\n      // 百分比拆分：95%Cotton 5%Elastane → 只在百分比前有空格或开头时拆分\r\n        const pctParts = splitPctLines(title);\r\n      if (pctParts.length > 1) {\r\n        titleLines = pctParts;\r\n        currentFsTitle = Math.floor(H * 0.055);\r\n        g.font = `bold ${currentFsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\r\n      } else {\r\n        const words = title.split(' ');\r\n        const mid = Math.floor(words.length / 2);\r\n        titleLines = [words.slice(0, mid).join(' '), words.slice(mid).join(' ')];\r\n        currentFsTitle = Math.floor(H * 0.055);\r\n        g.font = `bold ${currentFsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\r\n      }\r\n    } else {\r\n      titleLines = [title];\r\n    }\r\n  }\r\n\r\n  const ty = Math.floor(H * 0.06);\r\n  for (let i = 0; i < titleLines.length; i++) {\r\n    const ly = ty + i * Math.floor(currentFsTitle * 1.3);\r\n    drawTextWithStroke(titleLines[i], W / 2, ly, titleColor, titleStrokeRgba, 5);\r\n  }\r\n\r\n  // --- 副标题（333 无 subtitle） ---\r\n  const fsSub = Math.floor(H * 0.05);\r\n  g.font = `bold ${fsSub}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\r\n  const sy = ty + titleLines.length * Math.floor(currentFsTitle * 1.3) + Math.floor(currentFsTitle * 0.3);\r\n\r\n  // --- 标签行 ---\r\n  const fsTag = Math.floor(H * 0.03);\r\n  g.font = `bold ${fsTag}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\r\n  const tagParts = cleanedTags ? cleanedTags.split(SEPARATOR).filter(p => p) : [];\r\n  const tagMaxW = Math.floor(W * 0.88);\r\n  const partWidths = tagParts.map(p => g.measureText(p).width);\r\n  const sepW = g.measureText(SEPARATOR).width;\r\n  const totalW = tagParts.length > 0\r\n    ? partWidths.reduce((a, b) => a + b, 0) + (tagParts.length - 1) * sepW\r\n    : 0;\r\n\r\n  // 标签换行（移植自 L308-317）\r\n  let tagLines;\r\n  if (totalW > tagMaxW && tagParts.length > 1) {\r\n    let bestMid = 1, bestDiff = 999999;\r\n    for (let mid = 1; mid < tagParts.length; mid++) {\r\n      const w1 = partWidths.slice(0, mid).reduce((a, b) => a + b, 0) + Math.max(0, mid - 1) * sepW;\r\n      const w2 = partWidths.slice(mid).reduce((a, b) => a + b, 0) + Math.max(0, tagParts.length - mid - 1) * sepW;\r\n      const diff = Math.abs(w1 - w2);\r\n      if (diff < bestDiff) { bestDiff = diff; bestMid = mid; }\r\n    }\r\n    tagLines = [\r\n      tagParts.slice(0, bestMid).join(SEPARATOR),\r\n      tagParts.slice(bestMid).join(SEPARATOR)\r\n    ];\r\n  } else {\r\n    tagLines = cleanedTags ? [cleanedTags] : [];\r\n  }\r\n\r\n  const tagY = sy; // 333 无 subtitle，tagY = sy\r\n  const tagStroke = accentRgbSum > 382 ? 'rgba(0, 0, 0, 0.39)' : 'rgba(255, 255, 255, 0.47)';\r\n\r\n  for (let li = 0; li < tagLines.length; li++) {\r\n    const line = tagLines[li];\r\n    const ly = tagY + li * Math.floor(fsTag * 1.8);\r\n    drawTextWithStroke(line, W / 2, ly, accentColor, tagStroke, 3);\r\n  }\r\n\r\n  // --- badge：圆角黑底白字（移植自 L339-356） ---\r\n  if (badge) {\r\n    const fsBadge = Math.floor(H * 0.038);\r\n    g.font = `bold ${fsBadge}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\r\n    // badge 高度：使用实际测量（移植自 tb[3]-tb[1]+20）\r\n    const badgeMetrics = g.measureText(badge);\r\n    const badgeW = g.measureText(badge).width + 40;\r\n    const badgeH = (badgeMetrics.actualBoundingBoxAscent || fsBadge * 0.8) +\r\n                  (badgeMetrics.actualBoundingBoxDescent || fsBadge * 0.2) + 20;\r\n\r\n    let bx, by;\r\n    if (badgePos === 'br') {\r\n      bx = W - badgeW - Math.floor(W * 0.05);\r\n      by = H - badgeH - Math.floor(H * 0.05);\r\n    } else {\r\n      bx = (W - badgeW) / 2;\r\n      by = Math.floor(H * 0.45);\r\n    }\r\n\r\n    drawRoundedRect(bx, by, badgeW, badgeH, Math.floor(badgeH / 2));\r\n    g.fillStyle = badgeBgRgba;\r\n    g.fill();\r\n\r\n    g.fillStyle = 'rgb(255, 255, 255)';\r\n    g.textAlign = 'center';\r\n    g.textBaseline = 'middle';\r\n    g.fillText(badge, bx + badgeW / 2, by + badgeH / 2);\r\n  }\r\n\r\n  ctx.log('OK 333面料标注完成');\r\n}, {\r\n  timeoutMs: 120000,\r\n  preserveLegacySignals: true,\r\n});\r\n","444叠加后处理.js":"/**\n * 444 叠加后处理脚本（白底模式）— SDK v2.2 + @contract\n *\n * @contract\n * @needs canvas:main\n * @needs resources:cardImage\n * @supports single\n * @fallback alert\n * @timeout 10000\n *\n * @resource cardImage file \"白底卡片图\" from:user\n *\n * 通过 ctx.data.loadResource('cardImage') 主动获取白底卡片图（dataUrl），叠加到原图上。\n * 缺素材时由契约校验提前 alert 提示，不会执行到一半才崩。\n */\nCustomJsSDK.run(async ctx => {\n  const { canvas, ctx: g } = ctx;\n\n  // 资源发现：先探测 cardImage 是否可用\n  const hasCard = await ctx.data.hasResource('cardImage');\n  if (!hasCard) {\n    throw new Error('缺少 cardImage 叠加图片，请在后处理资源配置中选择图片');\n  }\n\n  // 加载卡片图 dataUrl\n  const cardDataUrl = await ctx.data.loadResource('cardImage');\n  const cardImg = new Image();\n  cardImg.crossOrigin = 'anonymous';\n  await new Promise((resolve, reject) => {\n    cardImg.onload = resolve;\n    cardImg.onerror = () => reject(new Error('卡片图加载失败'));\n    cardImg.src = cardDataUrl;\n  });\n\n  // 叠加到主画布\n  ctx.log('[444叠加] 叠加卡片图...');\n  // JPG 模板右侧常是整列纯白留空，直接整图覆盖会把衣服盖掉。\n  // 只忽略与右边缘连通的白色空白列，保留左侧模板的完整底色与内容；透明 PNG 仍原样叠加。\n  let sourceWidth=cardImg.naturalWidth||cardImg.width;\n  const sourceHeight=cardImg.naturalHeight||cardImg.height;\n  if(sourceWidth&&sourceHeight){\n    const probe=document.createElement('canvas');probe.width=sourceWidth;probe.height=sourceHeight;\n    const pg=probe.getContext('2d');pg.drawImage(cardImg,0,0);\n    const pixels=pg.getImageData(0,0,sourceWidth,sourceHeight).data;\n    let right=sourceWidth;\n    for(let x=sourceWidth-1;x>=0;x--){\n      let blank=true;\n      for(let y=0;y<sourceHeight;y++){\n        const i=(y*sourceWidth+x)*4;\n        if(pixels[i+3]>8&&(pixels[i]<245||pixels[i+1]<245||pixels[i+2]<245)){blank=false;break;}\n      }\n      if(!blank)break;right=x;\n    }\n    // 至少留出 10% 的连通空白才视为版式留白，避免误裁边缘抗锯齿。\n    if(right>0&&right<sourceWidth*.9){\n      g.drawImage(cardImg,0,0,right,sourceHeight,0,0,canvas.width*right/sourceWidth,canvas.height);\n    }else g.drawImage(cardImg,0,0,canvas.width,canvas.height);\n    probe.width=probe.height=0;\n  }else g.drawImage(cardImg,0,0,canvas.width,canvas.height);\n  ctx.log('[444叠加] 叠加完成');\n}, {\n  timeoutMs: 10000,\n  preserveLegacySignals: true,\n});\n\r\n","444扩图.js":"/**\n * 444 模特图扩图工具 — SDK v2.2 + @contract\n *\n * @contract\n * @needs canvas:main\n * @supports single\n * @fallback alert\n * @timeout 120000\n *\n * 对齐 Python 扩图工具 - 副本.py 的 expand_or_shrink_positional 逻辑。\n * 核心特点：\n *   - 衣服靠右，右侧留白 margin_ratio (默认 2%)\n *   - 目标格子占比 target = 0.35\n *   - 接缝处双向渐变混合 + 高斯模糊带\n *\n * ⚠️ 重要约定：扩图是修改原图本身的操作，确认替换后\n *   444.jpg 和 444原图.jpg 都会被替换为扩图后的新图（对齐 Python 版）。\n *   本脚本只负责把结果画到 canvas（即 444.jpg 的内容），\n *   reviewExpand 函数会负责同时写入 444原图.jpg。\n *\n * 依赖：ONNX Runtime Web (u2net.onnx) 从 chrome.runtime 加载\n *      ONNX session 通过 window 全局缓存跨脚本/跨注入复用（对齐 111卖点图后处理.js）\n */\nCustomJsSDK.run(async ctx => {\n  const { canvas, ctx: g, img } = ctx;\n  const TARGET = 0.35;\n  const MARGIN_RATIO = 0.02;\n  const w0 = img.width;\n  const h0 = img.height;\n\n  ctx.log('[444扩图] 原图尺寸: ' + w0 + 'x' + h0);\n\n  // ============================================================\n  // 抠图 / 网格分析：共享实现，见 SDK 的 ctx.rembg\n  //   111卖点图 / 111扩图 / 444扩图 三份实现实测逻辑一致（仅注释与 const/let 风格不同），\n  //   集中到 SDK 后 session 缓存键、320×320 归一化、LANCZOS 回缩放等细节只维护一处。\n  //   注意：sampleBgColor 与接缝混合**不在共享范围**（与 111扩图 的签名/算法不同，非重复实现）。\n  // ============================================================\n  const { getOrCreateU2NetSession, rembgRemoveBackground, gridAnalysis } = ctx.rembg;\n\n  // ============================================================\n  // 1. rembg 抠图 → alpha mask —— 已移到共享实现（见上方 ctx.rembg 解构）\n  // ============================================================\n\n  // ============================================================\n  // 2. 网格分析与衣服检测 —— 已移到共享实现（ctx.rembg.gridAnalysis）\n  // ============================================================\n\n  // ============================================================\n  // 3. 背景色采样\n  // ============================================================\n  function sampleBgColor(origImg, alphaCanvas) {\n    const w = origImg.width, h = origImg.height;\n    const tmpCanvas = document.createElement('canvas');\n    tmpCanvas.width = w;\n    tmpCanvas.height = h;\n    const oCtx = tmpCanvas.getContext('2d');\n    oCtx.drawImage(origImg, 0, 0);\n    const oData = oCtx.getImageData(0, 0, w, h).data;\n    const aData = alphaCanvas.getContext('2d').getImageData(0, 0, w, h).data;\n\n    let rSum = 0, gSum = 0, bSum = 0, count = 0;\n    for (let i = 0; i < aData.length; i += 4) {\n      if (aData[i] < 13) {\n        rSum += oData[i];\n        gSum += oData[i + 1];\n        bSum += oData[i + 2];\n        count++;\n      }\n    }\n    if (count > 0) return [Math.round(rSum / count), Math.round(gSum / count), Math.round(bSum / count)];\n    return [240, 240, 240];\n  }\n\n  // ============================================================\n  // 4. 接缝双向渐变混合 + 高斯模糊带\n  //    对齐 Python 版 _blend_seams + _blend_blur_band\n  //\n  // ⚠️ 与 111扩图.js 的 `blendSeamBands(targetCanvas, origW, origH, x, y)` **不是同一个函数**：\n  //    本函数入参是原图 Image，做双向渐变 + 高斯模糊带；111扩图 那份按「轴向 + 缝位置」\n  //    作用在已有画布上。两者算法与签名都不同，**不属重复实现，禁止合并**\n  //    （合并会改变出图结果）。命名相似纯属历史巧合。\n  // ============================================================\n  function blendSeams(newCanvas, origImg, offsetX, offsetY) {\n    const nc = newCanvas.getContext('2d');\n    const newW = newCanvas.width;\n    const newH = newCanvas.height;\n    const origW = origImg.width;\n    const origH = origImg.height;\n\n    const srcX0 = Math.max(0, -offsetX);\n    const srcY0 = Math.max(0, -offsetY);\n    const srcX1 = Math.min(origW, newW - offsetX);\n    const srcY1 = Math.min(origH, newH - offsetY);\n    const dstX0 = Math.max(0, offsetX);\n    const dstY0 = Math.max(0, offsetY);\n    const dstX1 = Math.min(newW, offsetX + origW);\n    const dstY1 = Math.min(newH, offsetY + origH);\n\n    const visibleW = srcX1 - srcX0;\n    const visibleH = srcY1 - srcY0;\n    const halfBlend = Math.max(20, Math.min(100, Math.floor(Math.min(visibleW, visibleH) * 0.06)));\n    const edgeSkip = Math.max(3, Math.floor(halfBlend * 0.2));\n\n    const origCanvas = document.createElement('canvas');\n    origCanvas.width = origW;\n    origCanvas.height = origH;\n    const origCtx = origCanvas.getContext('2d');\n    origCtx.drawImage(origImg, 0, 0);\n    const origData = origCtx.getImageData(0, 0, origW, origH).data;\n\n    const imgData = nc.getImageData(0, 0, newW, newH);\n    const data = imgData.data;\n\n    function getOrigPixel(x, y) {\n      x = Math.max(0, Math.min(origW - 1, x));\n      y = Math.max(0, Math.min(origH - 1, y));\n      const idx = (y * origW + x) * 4;\n      return [origData[idx], origData[idx + 1], origData[idx + 2]];\n    }\n\n    function getPixel(x, y) {\n      const idx = (y * newW + x) * 4;\n      return [data[idx], data[idx + 1], data[idx + 2]];\n    }\n\n    function setPixel(x, y, r, g, b) {\n      const idx = (y * newW + x) * 4;\n      data[idx] = r;\n      data[idx + 1] = g;\n      data[idx + 2] = b;\n    }\n\n    function lerp(c1, c2, t) {\n      return [\n        Math.round(c1[0] * (1 - t) + c2[0] * t),\n        Math.round(c1[1] * (1 - t) + c2[1] * t),\n        Math.round(c1[2] * (1 - t) + c2[2] * t)\n      ];\n    }\n\n    function ease(t) {\n      return (1 - Math.cos(t * Math.PI)) / 2;\n    }\n\n    if (srcY0 === 0 && offsetY > 0) {\n      const seamY = offsetY;\n      const origRefY = Math.min(edgeSkip, origH - 1);\n      const topStart = Math.max(0, seamY - halfBlend);\n      for (let y = topStart; y < seamY; y++) {\n        const t = ease((seamY - y) / halfBlend);\n        for (let x = dstX0; x < dstX1; x++) {\n          const sx = x - offsetX;\n          const origColor = getOrigPixel(Math.max(0, Math.min(origW - 1, sx)), origRefY);\n          const expandColor = getPixel(x, y);\n          const [r, g, b] = lerp(expandColor, origColor, t);\n          setPixel(x, y, r, g, b);\n        }\n      }\n      const botEnd = Math.min(dstY1, seamY + halfBlend);\n      for (let y = seamY; y < botEnd; y++) {\n        const t = ease((y - seamY) / halfBlend);\n        for (let x = dstX0; x < dstX1; x++) {\n          const sx = x - offsetX;\n          const origColor = getOrigPixel(Math.max(0, Math.min(origW - 1, sx)), y - offsetY);\n          const refColor = getOrigPixel(Math.max(0, Math.min(origW - 1, sx)), origRefY);\n          const [r, g, b] = lerp(origColor, refColor, t);\n          setPixel(x, y, r, g, b);\n        }\n      }\n    }\n\n    if (srcY1 === origH && offsetY + origH < newH) {\n      const seamY = offsetY + origH;\n      const origRefY = Math.max(origH - 1 - edgeSkip, 0);\n      const botEnd = Math.min(newH, seamY + halfBlend);\n      for (let y = seamY; y < botEnd; y++) {\n        const t = ease((y - seamY) / halfBlend);\n        for (let x = dstX0; x < dstX1; x++) {\n          const sx = x - offsetX;\n          const origColor = getOrigPixel(Math.max(0, Math.min(origW - 1, sx)), origRefY);\n          const expandColor = getPixel(x, y);\n          const [r, g, b] = lerp(origColor, expandColor, t);\n          setPixel(x, y, r, g, b);\n        }\n      }\n      const topStart = Math.max(dstY0, seamY - halfBlend);\n      for (let y = topStart; y < seamY; y++) {\n        const t = ease((seamY - y) / halfBlend);\n        for (let x = dstX0; x < dstX1; x++) {\n          const sx = x - offsetX;\n          const origColor = getOrigPixel(Math.max(0, Math.min(origW - 1, sx)), y - offsetY);\n          const refColor = getOrigPixel(Math.max(0, Math.min(origW - 1, sx)), origRefY);\n          const [r, g, b] = lerp(refColor, origColor, t);\n          setPixel(x, y, r, g, b);\n        }\n      }\n    }\n\n    if (srcX0 === 0 && offsetX > 0) {\n      const seamX = offsetX;\n      const origRefX = Math.min(edgeSkip, origW - 1);\n      const leftStart = Math.max(0, seamX - halfBlend);\n      for (let x = leftStart; x < seamX; x++) {\n        const t = ease((seamX - x) / halfBlend);\n        for (let y = dstY0; y < dstY1; y++) {\n          const sy = y - offsetY;\n          const origColor = getOrigPixel(origRefX, Math.max(0, Math.min(origH - 1, sy)));\n          const expandColor = getPixel(x, y);\n          const [r, g, b] = lerp(expandColor, origColor, t);\n          setPixel(x, y, r, g, b);\n        }\n      }\n      const rightEnd = Math.min(dstX1, seamX + halfBlend);\n      for (let x = seamX; x < rightEnd; x++) {\n        const t = ease((x - seamX) / halfBlend);\n        for (let y = dstY0; y < dstY1; y++) {\n          const sy = y - offsetY;\n          const origColor = getOrigPixel(x - offsetX, Math.max(0, Math.min(origH - 1, sy)));\n          const refColor = getOrigPixel(origRefX, Math.max(0, Math.min(origH - 1, sy)));\n          const [r, g, b] = lerp(origColor, refColor, t);\n          setPixel(x, y, r, g, b);\n        }\n      }\n    }\n\n    if (srcX1 === origW && offsetX + origW < newW) {\n      const seamX = offsetX + origW;\n      const origRefX = Math.max(origW - 1 - edgeSkip, 0);\n      const rightEnd = Math.min(newW, seamX + halfBlend);\n      for (let x = seamX; x < rightEnd; x++) {\n        const t = ease((x - seamX) / halfBlend);\n        for (let y = dstY0; y < dstY1; y++) {\n          const sy = y - offsetY;\n          const origColor = getOrigPixel(origRefX, Math.max(0, Math.min(origH - 1, sy)));\n          const expandColor = getPixel(x, y);\n          const [r, g, b] = lerp(origColor, expandColor, t);\n          setPixel(x, y, r, g, b);\n        }\n      }\n      const leftStart = Math.max(dstX0, seamX - halfBlend);\n      for (let x = leftStart; x < seamX; x++) {\n        const t = ease((seamX - x) / halfBlend);\n        for (let y = dstY0; y < dstY1; y++) {\n          const sy = y - offsetY;\n          const origColor = getOrigPixel(x - offsetX, Math.max(0, Math.min(origH - 1, sy)));\n          const refColor = getOrigPixel(origRefX, Math.max(0, Math.min(origH - 1, sy)));\n          const [r, g, b] = lerp(refColor, origColor, t);\n          setPixel(x, y, r, g, b);\n        }\n      }\n    }\n\n    nc.putImageData(imgData, 0, 0);\n\n    const blurPct = 0.05;\n\n    function blendBlurBand(axis, seam) {\n      const bw = Math.max(1, Math.round(Math.max(newW, newH) * blurPct));\n      const maxAxis = axis === 0 ? newH : newW;\n      const b0 = Math.max(0, seam - bw);\n      const b1 = Math.min(maxAxis, seam + bw);\n      if (b1 <= b0) return;\n\n      const sx = axis === 0 ? 0 : b0;\n      const sy = axis === 0 ? b0 : 0;\n      const sw = axis === 0 ? newW : b1 - b0;\n      const sh = axis === 0 ? b1 - b0 : newH;\n\n      const temp = document.createElement('canvas');\n      temp.width = newW;\n      temp.height = newH;\n      const tc = temp.getContext('2d');\n      tc.filter = `blur(${Math.max(3, bw)}px)`;\n      tc.drawImage(newCanvas, 0, 0);\n\n      const origBand = nc.getImageData(sx, sy, sw, sh);\n      const blurBand = tc.getImageData(sx, sy, sw, sh);\n      const outData = nc.createImageData(sw, sh);\n      const len = sw * sh;\n\n      for (let i = 0; i < len; i++) {\n        const coord = axis === 0 ? Math.floor(i / sw) + sy : (i % sw) + sx;\n        let dist = Math.abs(coord - seam) / bw;\n        if (dist > 1) dist = 1;\n        const t = 0.5 + 0.5 * Math.cos(dist * Math.PI);\n        const j = i * 4;\n        outData.data[j]   = origBand.data[j]   * (1 - t) + blurBand.data[j]   * t;\n        outData.data[j+1] = origBand.data[j+1] * (1 - t) + blurBand.data[j+1] * t;\n        outData.data[j+2] = origBand.data[j+2] * (1 - t) + blurBand.data[j+2] * t;\n        outData.data[j+3] = 255;\n      }\n      nc.putImageData(outData, sx, sy);\n    }\n\n    if (offsetY > 0) blendBlurBand(0, offsetY);\n    if (offsetY + origH < newH) blendBlurBand(0, offsetY + origH);\n    if (offsetX > 0) blendBlurBand(1, offsetX);\n    if (offsetX + origW < newW) blendBlurBand(1, offsetX + origW);\n  }\n\n  // ============================================================\n  // 5. 主流程\n  // ============================================================\n  ctx.log('[444扩图] 开始 rembg 抠图...');\n  const alphaCanvas = await rembgRemoveBackground(img);\n  ctx.log('[444扩图] rembg 完成');\n\n  const { clothCells, cellRatio, bbox } = gridAnalysis(alphaCanvas);\n  ctx.log('[444扩图] 格子占比: ' + (cellRatio * 100).toFixed(1) + '% 衣服格子: ' + clothCells + ' bbox: ' + bbox);\n\n  if (bbox === null) {\n    ctx.log('[444扩图] 未检测到衣服，不调整');\n    return;\n  }\n\n  const [top, bot, left, right] = bbox;\n  const scale = Math.sqrt(cellRatio / TARGET);\n  const newW = Math.round(w0 * scale);\n  const newH = Math.round(h0 * scale);\n\n  ctx.log('[444扩图] 目标占比: ' + TARGET.toFixed(2) + ' 缩放: ' + scale.toFixed(2) + '倍');\n  ctx.log('[444扩图] 新画布: ' + newW + 'x' + newH);\n\n  const offsetX = Math.round(newW * (1 - MARGIN_RATIO)) - right;\n  const offsetY = Math.floor((newH - h0) / 2);\n\n  const expandLeft = Math.max(0, offsetX);\n  const expandRight = Math.max(0, newW - (offsetX + w0));\n  const expandTop = Math.max(0, offsetY);\n  const expandBot = Math.max(0, newH - (offsetY + h0));\n\n  ctx.log('[444扩图] 各方向扩展: 上' + expandTop + ' 下' + expandBot + ' 左' + expandLeft + ' 右' + expandRight);\n\n  const bgColor = sampleBgColor(img, alphaCanvas);\n  ctx.log('[444扩图] 背景色: RGB(' + bgColor.join(',') + ')');\n\n  const newCanvas = document.createElement('canvas');\n  newCanvas.width = newW;\n  newCanvas.height = newH;\n  const nc2 = newCanvas.getContext('2d');\n\n  nc2.fillStyle = 'rgb(' + bgColor.join(',') + ')';\n  nc2.fillRect(0, 0, newW, newH);\n  nc2.drawImage(img, offsetX, offsetY);\n\n  blendSeams(newCanvas, img, offsetX, offsetY);\n\n  canvas.width = newW;\n  canvas.height = newH;\n  g.drawImage(newCanvas, 0, 0);\n\n  ctx.log('[444扩图] 完成');\n}, {\n  timeoutMs: 120000,\n  preserveLegacySignals: true,\n});\n","666领口图后处理.js":"/**\n * 666 领口细节图后处理脚本 — SDK v2.2 + @contract\n *\n * @contract\n * @needs canvas:main\n * @needs row:product\n * @supports single\n * @fallback alert\n * @timeout 120000\n *\n * @resource productRow row \"当前产品行（Excel）\" from:currentSet.row\n *\n * 数据来源：ctx.data.excelRow —— 当前导入 Excel 的当前产品行快照，按真实 Excel 列名取值。\n * 列名随类目变化，统一由 CategoryFieldRules 角色解析：\n *   领 → shirt / 帽衫 / 无帽卫衣 = 领型，t-shirt = 领子，polo 无此列；\n *   编织 → polo / shirt / t-shirt = 编织方法，帽衫 / 无帽卫衣 = 编织方式；\n *   衣服门襟 仅 shirt 有；设计 除 shirt 外都有。\n *\n * 完全对齐 Python image_review_regen_gui.py 的 _draw_detail_text_on_image 实现。\n * 移植自 L143-358（_get_detail_text_content + _draw_detail_text_on_image + _analyze_image_color）。\n */\nCustomJsSDK.run(async ctx => {\n  const { canvas, ctx: g } = ctx;\n  // 当前产品行快照；缺失即报错，不静默回退到空值\n  if (!ctx.data.excelRow) throw new Error('缺少当前产品行数据（excelRow）');\n\n  // ============================================================\n  // 常量（移植自 L114-123）\n  // ============================================================\n  // ============================================================\n  // 工具函数 —— 共享实现放在 SDK 的 ctx.draw（单一真源），本脚本只做绑定与适配\n  //\n  // 此前 222/333/666 各自内联同一套 5 个绘制函数 + tagList（共约 300 行重复），\n  // 且已出现漂移（标题断行正则只在 333 修过、变量名 t/tt 不一致）。\n  // 现统一由 ctx.draw 提供，调用点写法保持不变。\n  // ============================================================\n  const { rgbToHsv, hsvToRgb, cleanText, sameDisplayText, tagList, splitPctLines } = ctx.draw;\n\n  /** _clean：空值/none/n/a 归一为空字符串 */\n  const _clean = (val) => (!val || ['none', 'n/a', 'na'].includes(val.toLowerCase())) ? '' : val;\n\n  /** 绑定本脚本的 2D 上下文 g（调用点不变） */\n  function drawTextWithStroke(text, x, y, fillColor, strokeColor, offset) {\n    ctx.draw.drawTextWithStroke(g, text, x, y, fillColor, strokeColor, offset);\n  }\n\n  function drawRoundedRect(x, y, w, h, r) {\n    ctx.draw.drawRoundedRect(g, x, y, w, h, r);\n  }\n\n  // ============================================================\n  // 读取属性（移植自 L423-436）\n  // ============================================================\n  // 领列随类目变化（polo 无此列）：shirt / 帽衫 / 无帽卫衣 → 领型；t-shirt → 领子\n  const collarVal = _clean(ctx.data.optionalRole('collar').value);\n  const collarType = collarVal;\n  // 衣服门襟：仅 shirt 有此列\n  const placket = _clean(ctx.data.optionalRole('placket').value);\n  // 编织列随类目变化：polo / shirt / t-shirt → 编织方法；帽衫 / 无帽卫衣 → 编织方式\n  const weave = _clean(ctx.data.role('weave').value);\n  const design = _clean(ctx.data.optionalRole('design').value);\n  const groupVal = ctx.data.category();\n\n  // ============================================================\n  // 颜色分析（移植自 _analyze_image_color L78-110）\n  // ============================================================\n  const W = canvas.width;\n  const H = canvas.height;\n  let rs = 0, gs = 0, bs = 0, ct = 0;\n  try {\n    const imageData = g.getImageData(0, 0, W, H);\n    const data = imageData.data;\n    for (let y = 0; y < H; y += 10) {\n      for (let x = 0; x < W; x += 10) {\n        const idx = (y * W + x) * 4;\n        const r = data[idx], g2 = data[idx + 1], b = data[idx + 2];\n        const lum = r * 299 + g2 * 587 + b * 114;\n        if (lum < 600000 && lum > 30000) {\n          rs += r; gs += g2; bs += b; ct++;\n        }\n      }\n    }\n  } catch (e) { /* 跨域等异常，降级使用默认色 */ }\n\n  let titleColor, titleStrokeRgba, accentColor, accentRgbSum;\n  let badgeBgRgba;\n\n  if (ct > 0) {\n    const avgR = Math.floor(rs / ct);\n    const avgG = Math.floor(gs / ct);\n    const avgB = Math.floor(bs / ct);\n    const brightness = Math.floor((avgR * 299 + avgG * 587 + avgB * 114) / 1000);\n    if (brightness > 150) {\n      titleColor = 'rgb(40, 40, 50)';\n      titleStrokeRgba = 'rgba(255, 255, 255, 0.39)';\n    } else {\n      titleColor = 'rgb(255, 255, 255)';\n      titleStrokeRgba = 'rgba(0, 0, 0, 0.39)';\n    }\n    const [h, s, v] = rgbToHsv(avgR, avgG, avgB);\n    // accent_color：相邻色（色相+0.1）\n    const h2 = (h + 0.1) % 1.0;\n    const s2 = Math.min(1.0, s * 1.5);\n    const v2 = brightness > 150 ? 0.4 : 0.7;\n    const [ar, ag, ab] = hsvToRgb(h2, s2, v2);\n    accentColor = `rgb(${ar}, ${ag}, ${ab})`;\n    accentRgbSum = ar + ag + ab;\n    // badge_bg：互补色（色相+0.5）\n    const h3 = (h + 0.5) % 1.0;\n    const s3 = Math.max(0.3, Math.min(0.6, s * 1.2));\n    const v3 = v < 0.5 ? 0.75 : 0.35;\n    const [br, bg, bb] = hsvToRgb(h3, s3, v3);\n    badgeBgRgba = `rgba(${br}, ${bg}, ${bb}, 0.9)`;\n  } else {\n    titleColor = 'rgb(40, 40, 50)';\n    titleStrokeRgba = 'rgba(255, 255, 255, 0.39)';\n    accentColor = 'rgb(120, 120, 120)';\n    accentRgbSum = 360;\n    badgeBgRgba = 'rgba(60, 65, 75, 0.9)';\n  }\n\n  // ============================================================\n  // 文字内容生成（移植自 _get_detail_text_content L168-181）\n  // ============================================================\n  let title = collarVal || weave || design;\n  if (!title) throw new Error('缺少领型、编织方法和设计属性，无法标注领口图');\n  const isShirt = groupVal === 'shirt';\n  const allTags = isShirt ? tagList(collarType, placket) : tagList(weave, design);\n  let tags, subtitle;\n  if (allTags.length > 0) {\n    // 取最长标签（移植自 max(all_tags, key=len)）\n    tags = allTags.reduce((a, b) => a.length > b.length ? a : b);\n    subtitle = '';\n  } else {\n    tags = '';\n    subtitle = collarVal ? collarVal.toUpperCase() : '';\n  }\n  const badge = '';\n  const badgePos = 'br';\n\n  // cleanText 清理\n  title = cleanText(title);\n  subtitle = cleanText(subtitle);\n  tags = cleanText(tags);\n  if (sameDisplayText(tags, title)) tags = '';\n\n  // ============================================================\n  // 绘制（移植自 _draw_detail_text_on_image L248-358）\n  // ============================================================\n  const SEPARATOR = ' ';\n  g.textAlign = 'center';\n  g.textBaseline = 'top';\n\n  // --- 大标题 ---\n  const fsTitle = Math.floor(H * 0.07);\n  let currentFsTitle = fsTitle;\n  g.font = `bold ${fsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n  const maxW = Math.floor(W * 0.88);\n\n  // 标题换行：\\n → 百分比拆分 → 空格二分（移植自 L258-276）\n  let titleLines;\n  if (title.includes('\\n')) {\n    titleLines = title.split('\\n');\n  } else {\n    const titleWidth = g.measureText(title).width;\n    if (titleWidth > maxW) {\n      // 百分比拆分：95%Cotton 5%Elastane\n      const pctParts = splitPctLines(title);\n      if (pctParts.length > 1) {\n        titleLines = pctParts;\n        currentFsTitle = Math.floor(H * 0.055);\n        g.font = `bold ${currentFsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n      } else {\n        const words = title.split(' ');\n        const mid = Math.floor(words.length / 2);\n        titleLines = [words.slice(0, mid).join(' '), words.slice(mid).join(' ')];\n        currentFsTitle = Math.floor(H * 0.055);\n        g.font = `bold ${currentFsTitle}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n      }\n    } else {\n      titleLines = [title];\n    }\n  }\n\n  const ty = Math.floor(H * 0.06);\n  for (let i = 0; i < titleLines.length; i++) {\n    const ly = ty + i * Math.floor(currentFsTitle * 1.3);\n    drawTextWithStroke(titleLines[i], W / 2, ly, titleColor, titleStrokeRgba, 5);\n  }\n\n  // --- 副标题 ---\n  const fsSub = Math.floor(H * 0.05);\n  g.font = `bold ${fsSub}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n  const sy = ty + titleLines.length * Math.floor(currentFsTitle * 1.3) + Math.floor(currentFsTitle * 0.3);\n\n  if (subtitle) {\n    const subStroke = accentRgbSum > 382 ? 'rgba(0, 0, 0, 0.39)' : 'rgba(255, 255, 255, 0.47)';\n    drawTextWithStroke(subtitle, W / 2, sy, accentColor, subStroke, 3);\n  }\n\n  // --- 标签行 ---\n  const fsTag = Math.floor(H * 0.03);\n  g.font = `bold ${fsTag}px \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif`;\n  const tagParts = tags ? tags.split(SEPARATOR).filter(p => p) : [];\n  const tagMaxW = Math.floor(W * 0.88);\n  const partWidths = tagParts.map(p => g.measureText(p).width);\n  const sepW = g.measureText(SEPARATOR).width;\n  const totalW = tagParts.length > 0\n    ? partWidths.reduce((a, b) => a + b, 0) + (tagParts.length - 1) * sepW\n    : 0;\n\n  // 标签换行（移植自 L308-317）\n  let tagLines;\n  if (totalW > tagMaxW && tagParts.length > 1) {\n    let bestMid = 1, bestDiff = 999999;\n    for (let mid = 1; mid < tagParts.length; mid++) {\n      const w1 = partWidths.slice(0, mid).reduce((a, b) => a + b, 0) + Math.max(0, mid - 1) * sepW;\n      const w2 = partWidths.slice(mid).reduce((a, b) => a + b, 0) + Math.max(0, tagParts.length - mid - 1) * sepW;\n      const diff = Math.abs(w1 - w2);\n      if (diff < bestDiff) { bestDiff = diff; bestMid = mid; }\n    }\n    tagLines = [\n      tagParts.slice(0, bestMid).join(SEPARATOR),\n      tagParts.slice(bestMid).join(SEPARATOR)\n    ];\n  } else {\n    tagLines = tags ? [tags] : [];\n  }\n\n  const tagY = sy + (subtitle ? Math.floor(fsSub * 1.8) : 0);\n  const tagStroke = accentRgbSum > 382 ? 'rgba(0, 0, 0, 0.39)' : 'rgba(255, 255, 255, 0.47)';\n\n  for (let li = 0; li < tagLines.length; li++) {\n    const line = tagLines[li];\n    const ly = tagY + li * Math.floor(fsTag * 1.8);\n    drawTextWithStroke(line, W / 2, ly, accentColor, tagStroke, 3);\n  }\n\n  // 666 无 badge\n\n  ctx.log('OK 666领口标注完成');\n}, {\n  timeoutMs: 120000,\n  preserveLegacySignals: true,\n});\n","测试资源.js":"/**\n * 测试资源脚本 — SDK v2.2 + @contract\n *\n * @contract\n * @needs canvas:main\n * @needs resources:images\n * @needs resources:infoFile\n * @supports single\n * @fallback alert\n * @timeout 60000\n *\n * @resource images folder \"图片文件夹\" from:user\n * @resource infoFile file \"信息文件\" from:user\n *\n * 测试脚本：从文件夹随机取2张图片拼到画布上，并显示txt内容\n * 通过 ctx.data.loadResource 主动获取 images（folder 类型）和 infoFile（file 类型）\n */\nCustomJsSDK.run(async ctx => {\n  const { canvas, ctx: g } = ctx;\n\n  // images: folder 类型资源（{文件名: dataURL}）\n  const imageFiles = (await ctx.data.loadResource('images')) || {};\n  // infoFile: file 类型资源（dataURL 字符串）\n  const infoFileUrl = await ctx.data.loadResource('infoFile');\n\n  ctx.log('[测试脚本] 资源列表: images=' + Object.keys(imageFiles).length + ' 个, infoFile=' + (infoFileUrl ? '存在' : '不存在'));\n\n  const imageNames = Object.keys(imageFiles).filter(name => /\\.(jpg|jpeg|png|webp|gif)$/i.test(name));\n  ctx.log('[测试脚本] 图片文件列表: ' + imageNames.join(', '));\n\n  if (imageNames.length < 2) {\n    g.fillStyle = 'red';\n    g.font = '30px sans-serif';\n    g.fillText('图片不足2张，当前: ' + imageNames.length, 50, 100);\n    return;\n  }\n\n  const shuffled = imageNames.sort(() => Math.random() - 0.5);\n  const picked = shuffled.slice(0, 2);\n  ctx.log('[测试脚本] 随机选中: ' + picked.join(', '));\n\n  // 并行加载两张图片（onerror 也 resolve，避免单张失败阻塞整批；未加载的图 width=0，后续 scale=0 自然不显示）\n  const imgs = await Promise.all(picked.map(name => {\n    return new Promise(resolve => {\n      const tmpImg = new Image();\n      tmpImg.onload = () => resolve(tmpImg);\n      tmpImg.onerror = () => resolve(tmpImg);\n      tmpImg.src = imageFiles[name];\n    });\n  }));\n\n  const w = canvas.width;\n  const h = canvas.height;\n\n  g.fillStyle = '#1a1a2e';\n  g.fillRect(0, 0, w, h);\n\n  const thumbW = w / 2 - 20;\n  const thumbH = h - 120;\n\n  for (let i = 0; i < 2; i++) {\n    const x = 10 + i * (thumbW + 20);\n    const y = 60;\n\n    const scale = Math.min(thumbW / imgs[i].width, thumbH / imgs[i].height);\n    const dw = imgs[i].width * scale;\n    const dh = imgs[i].height * scale;\n    const dx = x + (thumbW - dw) / 2;\n    const dy = y + (thumbH - dh) / 2;\n\n    g.drawImage(imgs[i], dx, dy, dw, dh);\n\n    g.fillStyle = 'white';\n    g.font = '14px sans-serif';\n    g.fillText(picked[i], dx, dy - 5);\n  }\n\n  g.fillStyle = '#00d4ff';\n  g.font = 'bold 20px sans-serif';\n  g.fillText('随机图片测试 - 共' + imageNames.length + '张', 20, 35);\n\n  if (infoFileUrl) {\n    g.fillStyle = '#88ff88';\n    g.font = '14px sans-serif';\n    g.fillText('信息文件: 已配置', 20, h - 20);\n  } else {\n    g.fillStyle = '#ff8888';\n    g.font = '14px sans-serif';\n    g.fillText('信息文件: 未配置', 20, h - 20);\n  }\n}, {\n  timeoutMs: 60000,\n  preserveLegacySignals: true,\n});\n"};
window.CustomStepBuiltinOverlay={"name":"444_品牌服务叠加图.jpg","value":"data:image/jpeg;base64,"};
for(const step of window.CustomStepDefaults)for(const script of step.postprocess||[])if(!script.code&&window.CustomStepBuiltinScripts[script.name])script.code=window.CustomStepBuiltinScripts[script.name];
